  const p2=`கல்வித் திறன் மதிப்பீடு: அடிப்படை கல்வி — ${v252BandLabel(b.foundation,lang)}； ஆரம்ப/தொடக்கப் பள்ளி — ${v252BandLabel(b.primary,lang)}； மேல்நிலைப் பள்ளி — ${v252BandLabel(b.secondary,lang)}； உயர்நிலை/தேர்வு கட்டம் — ${v252BandLabel(b.higherSecondary,lang)}； உயர்கல்வி — ${v252BandLabel(higher,lang)}. கவனம்/நினைவுத் தொடர்ச்சி — ${v252BandLabel(conc,lang)}； தேர்வு/போட்டி செயல்திறன் — ${v252BandLabel(exam,lang)}.`;
  const p3=higher==='strong'||higher==='support'?`உயர்கல்விக்கான பிறப்பு வாக்குறுதி முற்றிலும் மறுக்கப்படவில்லை; ${higher==='strong'?'நல்ல அடித்தளம் தெளிவாக உள்ளது':'சாத்தியம் உள்ளது, ஆனால் course fit, குடும்ப ஆதரவு மற்றும் சரியான காலத் தேர்வு பலனை நிர்ணயிக்கும்'}. “அடிப்படை கல்வியோடு கட்டாயமாக முடியும்” என்று இந்த அமைப்பை வாசிக்கக் காரணம் இல்லை.`:higher==='mixed'?`உயர்கல்வி சாத்தியம் நிபந்தனை சார்ந்தது. பள்ளிக் கல்விக்குப் பிறகு academic degree மட்டும் அல்ல, தொழில்நுட்ப/திறன்/தொழிற்பயிற்சி வழியும் உண்மையான திறனை வெளிப்படுத்தலாம். சரியான தசை மற்றும் கல்விச் சூழல் கிடைத்தால் படிப்பு மீண்டும் உயர முடியும்.`:`உயர்கல்விப் பாதையில் கூடுதல் தடைகள் அல்லது ஆர்வ மாறுபாடு இருக்கலாம்; இதை “படிப்பு முடியாது” என்று கூறாமல், அடித்தளப் பாடங்களை வலுப்படுத்துதல், practical/skill route, நல்ல ஆசிரியர் மற்றும் காலத் தேர்வு மூலம் capacity-ஐ காக்க வேண்டிய அமைப்பாக வாசிக்க வேண்டும்.`;
  const p4=`காரக கிரக நிலை: ${strong.length?`${strong.map(x=>v251Planet(x,lang)).join(', ')} ஒப்பீட்டளவில் கல்வியை தாங்கும் பக்கம் உள்ளது.`:'ஒரே ஒரு காரக கிரகம் மட்டும் முழு கல்வி பலனை நிர்ணயிக்கவில்லை.'}${weak.length?` ${weak.map(x=>v251Planet(x,lang)).join(', ')} பகுதியில் பலம் குறைந்திருப்பதால் அந்த கிரகம் குறிக்கும் திறனை நடைமுறை பழக்கத்தால் ஆதரிக்க வேண்டும்.`:''}`;
  const p5=weak.includes('Mercury')?'புதன் பலம் குறைந்தால் தினசரி குறுகிய revision, எழுதிப் பயிற்சி, கணக்கு/மொழி அடித்தளத்தை சிறு பகுதிகளாகப் பிரித்தல் முதன்மை. பாரம்பரியமாக புதன் தொடர்பான புதன்கிழமை ஒழுங்கு, விஷ்ணு/புதன் பிரார்த்தனை அல்லது பச்சை நிறத்தை நினைவூட்டலாக பயன்படுத்தலாம்; இது படிப்புக்கு மாற்றாக அல்ல.':weak.includes('Moon')?'சந்திர பலம் குறைந்தால் தூக்கம், உணவு நேரம், உணர்ச்சி பாதுகாப்பு மற்றும் படிப்பு நேர ஒழுங்கு முதலில் சரியாக இருக்க வேண்டும். பாரம்பரியமாக திங்கள் பிரார்த்தனை/சந்திர மன அமைதி வழிபாடு துணையாக இருக்கலாம்.':weak.includes('Jupiter')?'குரு பலம் குறைந்தால் நல்ல ஆசிரியர்/mentor, concepts புரிந்துகொள்ளும் முறையை வலுப்படுத்துதல் மற்றும் நீண்டகால course guidance முக்கியம். பாரம்பரியமாக வியாழன் குரு வழிபாடு/அறிவுத் தானம் துணையாக இருக்கலாம்.':'பரிகாரத்தில் முதலில் நல்ல ஆசிரியர், உறக்கம், தினசரி revision, subject-fit மற்றும் அளவிடக்கூடிய practice; பாரம்பரிய வழிபாடு வேண்டுமானால் துணை மட்டுமே.';
  return {house:'education',title:'கல்வித் திறன், பள்ளி வளர்ச்சி மற்றும் உயர்கல்வி சாத்தியம்',paragraphs:[p1,p2,p3,p4,p5]};
