function synthMatching(e){
 const build=lang=>{
  const good=num(e?.poruthamGood),total=num(e?.poruthamTotal,10),b=num(e?.brideBalance),g=num(e?.groomBalance),sum=b+g;
  const intro=lang==='ta'?`இருவரின் வாழ்க்கை நடை எங்கு ஒத்துப்போகலாம், எந்த விஷயத்தை முன்பே பேசித் தெளிவுபடுத்த வேண்டும் என்பதை இந்த வாசிப்பு விளக்குகிறது. நட்சத்திரப் பொருத்தத்தில் ${good}/${total} அம்சங்கள் ஆதரிக்கின்றன. பிறப்பு ஜாதகம், நவாம்சம், தோஷ விலக்கு மற்றும் இருவரின் காலநிலை ஆகியவற்றையும் சேர்த்தே முழு முடிவு பார்க்கப்படுகிறது.`:`This reading explains where your ways of living may fit together and which expectations are worth discussing early. The star comparison supports ${good} of ${total} factors. The full assessment also considers the birth charts, Navamsa, applicable dosha exceptions and the two timelines.`;
  const clusterNotesTa=[
   'குணநிலை, மனம் மற்றும் பேச்சு பகுதியில் உடனடி reaction-ஐ விட புரிதல், கேட்பது மற்றும் பதில் சொல்லும் வேகம் முக்கியம்.',
   'அன்பு, எதிர்பார்ப்பு மற்றும் நெருக்கம் பகுதியில் சொல்லப்படாத தேவையை விட தெளிவான எல்லை மற்றும் பாதுகாப்பு முக்கியம்.',
   'வீடு, குடும்பம் மற்றும் பணநிலையில் அன்பை விட தினசரி ஒழுங்கு, குடும்ப எல்லை மற்றும் பணத் தெளிவு அதிக தாக்கம் தரும்.',
   'தொழில், பொறுப்பு மற்றும் முடிவு பகுதியில் ஒருவரின் இலக்கு மற்றவரின் வாழ்க்கைத் திட்டத்துடன் எப்படிச் சேர்கிறது என்பதே சோதனை.',
   'மோதல், சமரசம், நம்பிக்கை பகுதியில் பிரச்சினை இல்லாமை அல்ல; சண்டைக்கு பிறகு எப்படி மீள்கிறார்கள் என்பதே நீண்டகால தரத்தை தீர்மானிக்கும்.',
   'சமூக வாழ்க்கை, குழந்தைகள் மற்றும் அறிவுப் பகிர்வில் எதிர்கால மதிப்புகள், கற்றல் மற்றும் care-style ஒரே திசைக்கு வருகிறதா என்பதை பார்க்க வேண்டும்.',
   'பயணம், தினசரி வாழ்க்கை, சொத்து மற்றும் நீண்டகால முதிர்ச்சியில் காலத்தோடு முடிவுகள் ஒன்றுக்கொன்று பொருந்தும் திறன் முக்கியம்.'
  ],clusterNotesEn=[
   'For temperament, mind and communication, understanding and response speed matter more than the absence of immediate reaction.',
   'For affection, expectations and intimacy, clear boundaries and emotional safety matter more than unspoken need.',
   'For home, family and money, daily rhythm, family boundaries and financial clarity often matter more than affection alone.',
   'For career, responsibility and decisions, the key test is whether one partner’s goals fit the other partner’s life plan.',
   'For conflict, repair and trust, long-term quality depends less on avoiding conflict and more on how the pair repairs after it.',
   'For social life, children and shared learning, future values, learning style and care patterns need to move toward a shared direction.',
   'For travel, routine, assets and long-term maturity, the key is whether decisions continue to fit each other as life changes.'
  ];
  const clusters=arr(e?.clusters).map((c,ci)=>{const b=num(c.brideAvg),g=num(c.groomAvg),diff=Math.abs(b-g),title=lang==='ta'?text(c.titleTa):text(c.titleEn),score=lang==='ta'?`பெண் ${signed(b)} · ஆண் ${signed(g)}.`:`Bride ${signed(b)} · Groom ${signed(g)}.`;const note=lang==='ta'?(clusterNotesTa[ci]||`${title} பகுதியில் தனித்த நடைமுறை விளைவுகள் கீழே பிரிக்கப்படுகின்றன.`):(clusterNotesEn[ci]||`Distinct practical consequences are separated below for ${title}.`);const bal=lang==='ta'?(diff>=1.5?`${title} பகுதியில் ஆதரவு சமமாக இல்லை; வலுவான பக்கம் கட்டுப்பாட்டாக அல்ல, சமநிலையாக பயன்படுத்தப்பட வேண்டும்.`:`${title} பகுதியில் ஆதரவு நெருக்கமாக இருப்பதால் வேறுபாடு வரும் இடத்தை நடைமுறை ஒப்பந்தம் தீர்மானிக்கும்.`):(diff>=1.5?`Support is uneven in ${title}; the stronger side should be used for balance rather than control.`:`Support is relatively close in ${title}, so practical agreements decide how differences are handled.`);return {title,evidence:[score,`${note} ${bal}`]}});
  const topics=arr(e?.topics).map(t=>v253MatchingTopic(t,lang,e)),timing=compactTiming(e,lang);
  return {intro,ageNote:matchingAgeNote(e,lang),verdict:pickLang(e?.verdict,lang),clusters,topics,timing};
 };
 return {ok:true,nonAI:true,engine:VERSION,ta:build('ta'),en:build('en')};
}

function synthesize(kind,evidence){
 if(kind==='horoscope')return v253CleanReport(synthHoroscope(evidence||{}));
 if(kind==='matching')return v253CleanReport(synthMatching(evidence||{}));
 throw new Error('Unsupported prediction synthesis kind.');
}

// V253: explain supplied chart evidence. Never manufacture placements or dates.
function v253ContextFrame(e,lang){const c=e.context||{},ta=lang==='ta',p=[];if(e.referenceDate)p.push(ta?`பலன் பார்க்கும் தேதி: ${e.referenceDate}`:`Reference date: ${e.referenceDate}`);if(c.age!=null)p.push(ta?`வயது: ${c.age}`:`Age: ${c.age}`);if(c.birthPlace)p.push(ta?`பிறந்த இடம்: ${c.birthPlace}`:`Birthplace: ${c.birthPlace}`);if(c.residence)p.push(ta?`தற்போதைய வசிப்பிடம்: ${c.residence}`:`Current residence: ${c.residence}`);return p.join(' · ')}
function v253Unique(xs){const seen=new Set();return xs.map(text).filter(s=>{const k=s.toLocaleLowerCase().replace(/[\s.,;:!?“”"'—–-]+/g,' ').trim();if(!k||seen.has(k))return false;seen.add(k);return true})}
const V253_HOUSE=[null,
 ['You are likely to make a better impression when you can decide how to approach a task. Taking ownership helps confidence grow through experience rather than through constant reassurance.','மற்றவர் சொல்லும் முறையை அப்படியே பின்பற்றுவதை விட, ஒரு வேலையை எப்படிச் செய்வது என்று நீங்களே திட்டமிடும்போது உங்கள் திறமை வெளிப்படலாம். சிறிய பொறுப்புகளை முடித்த அனுபவமே தன்னம்பிக்கையை வளர்க்கும்.', 'When personal expectations become too demanding, even a useful correction can feel like criticism. Give yourself time to reconsider a decision without treating that change as a loss of dignity.','உங்கள்மீது நீங்களே அதிக எதிர்பார்ப்பு வைத்துக்கொள்ளும்போது, சாதாரணத் திருத்தமும் குறை கூறுவது போலத் தோன்றலாம். முடிவை மாற்ற வேண்டியிருந்தால் அது சுயமரியாதைக் குறைவு என்று எண்ணாமல் மறுபரிசீலனை செய்ய இடம் கொடுங்கள்.'],
 ['Your words and the way you honour family commitments can become an important source of trust. A steady approach to shared resources is more useful here than trying to impress others through spending.','நீங்கள் பேசும் விதமும் குடும்பத்திற்கு அளித்த வாக்கைக் காப்பாற்றுவதும் நம்பிக்கையை உருவாக்கும். பிறர் பாராட்டுக்காகச் செலவிடுவதை விட குடும்பத் தேவைகளைத் தொடர்ந்து நிறைவேற்றுவதில் உங்கள் பலம் தெரியலாம்.', 'Money and family expectations may become entangled: agreeing to help someone can later feel like an obligation you cannot reduce. State what you can realistically contribute before making a promise.','பணம் கொடுத்து உதவுவது பின்னர் குறைக்க முடியாத குடும்பக் கடமையாக மாறலாம். அன்பின் காரணமாக உடனே ஒப்புக்கொள்வதற்கு முன் எவ்வளவு உதவ முடியும் என்பதைத் தெளிவாகச் சொல்லுவது உறவையும் பாதுகாக்கும்.'],
 ['Progress can come from skills you practise yourself: explaining, writing, organising or following up a task. A modest effort repeated consistently can take you further than waiting for a perfect opening.','பேசுவது, எழுதுவது, ஒழுங்குபடுத்துவது, தொடங்கிய வேலையை முடிப்பது போன்ற சுயமாக வளர்த்த திறன்கள் முன்னேற்றத்திற்கு உதவலாம். பெரிய வாய்ப்புக்காகக் காத்திருப்பதை விட தொடர்ந்து செய்யும் சிறிய முயற்சி பலன் தரக்கூடும்.', 'Effort may be scattered across several interests, or comparisons with siblings and peers may disturb your pace. Finish one useful piece of work before taking on the next commitment.','பல வேலைகளை ஒரே நேரத்தில் தொடங்குவதால் முயற்சி சிதறலாம்; சகோதரர் அல்லது நண்பருடன் ஒப்பிடுவதும் மனநிறைவைக் குறைக்கலாம். ஒரு வேலையின் முடிவு கைக்கு வந்த பிறகு அடுத்த முயற்சியை விரிவாக்குவது நல்லது.'],
 ['A settled home environment helps you think clearly and use your abilities with less strain. Support from a caregiver, a familiar place or a reliable study routine may matter more than outward luxury.','வீட்டில் அமைதி இருந்தால் உங்கள் சிந்தனையும் செயல்திறனும் நன்றாக வெளிப்படலாம். வெளிப்படையான வசதிகளை விட நம்பிக்கையான உறவு, பழகிய சூழல், தடையில்லாத படிப்பு அல்லது வேலை நேரம் உங்களுக்கு அதிக நிம்மதி தரலாம்.', 'Family demands and your need for peace may pull in different directions. A change of home or property purchase alone will not resolve an unsettled routine; clarify responsibilities within the household first.','குடும்பத் தேவைகளும் உங்களுக்கு வேண்டிய அமைதியும் சில நேரம் முரண்படலாம். வீடு மாறுவதாலோ சொத்து வாங்குவதாலோ மட்டும் தினசரி சிக்கல் தீராது; வீட்டுப் பொறுப்புகளை யார் கவனிப்பது என்பதை முதலில் பேசித் தீர்மானியுங்கள்.'],
 ['You may do well when learning allows you to understand a pattern and then express it in your own way. Creative work, teaching or patient guidance can turn knowledge into something others value.','ஒரு விஷயத்தின் அடிப்படையைப் புரிந்துகொண்டு உங்கள் சொந்த முறையில் விளக்கும்போது திறமை நன்றாகத் தெரியலாம். படைப்பாற்றல், கற்பித்தல், பொறுமையான வழிகாட்டல் ஆகியவற்றின் மூலம் தெரிந்த அறிவு பிறருக்குப் பயன்படலாம்.', 'A strong wish for a particular result can make uncertainty difficult to tolerate. Leave room for revision in studies and creative work, and avoid measuring family happiness through one expected milestone.','நினைத்த முடிவு கிடைக்க வேண்டும் என்ற எதிர்பார்ப்பு அதிகமானால் காத்திருப்பது சிரமமாகலாம். படிப்பு, படைப்புப் பணி போன்றவற்றில் திருத்தத்திற்கு இடம் கொடுங்கள்; குடும்ப மகிழ்ச்சியை ஒரு குறிப்பிட்ட நிகழ்வுடன் மட்டும் இணைக்க வேண்டாம்.'],
 ['You can build reliability by dealing with practical problems that others postpone. A clear routine, defined responsibilities and patient follow-through make demanding work more manageable.','மற்றவர்கள் ஒத்திப்போடும் நடைமுறைச் சிக்கலை எடுத்துச் சரிசெய்வதன் மூலம் நம்பகத்தன்மை உருவாகலாம். தெளிவான வேலை ஒழுங்கும் பொறுப்புப் பிரிவும் இருந்தால் சிரமமான பணியையும் படிப்படியாக முடிக்கலாம்.', 'Too many small obligations may leave you busy without feeling that you have moved forward. Distinguish essential work from tasks you accepted merely because it was difficult to say no.','சிறுசிறு பொறுப்புகள் சேர்ந்து நாள் முழுவதும் வேலை செய்தும் முன்னேற்றம் இல்லை என்ற உணர்வு வரலாம். அவசியமான வேலை எது, மறுக்க முடியாமல் ஏற்ற வேலை எது என்பதைப் பிரித்துப் பார்ப்பது சுமையைக் குறைக்கும்.'],
 ['Working with another person can reveal abilities that solitary effort does not bring out. Relationships and client work are more productive when expectations are discussed before either side assumes agreement.','தனியாகச் செய்யும்போது தெரியாத சில திறன்கள் மற்றவருடன் இணைந்து செயல்படும்போது வெளிப்படலாம். உறவிலும் வாடிக்கையாளர் தொடர்பிலும் எதிர்பார்ப்புகளை ஆரம்பத்திலேயே பேசுவது ஒத்துழைப்பை வளர்க்கும்.', 'Differences in pace or expectations may be mistaken for a lack of care. Before deciding that a relationship is unworkable, identify the specific promise, boundary or responsibility on which you disagree.','செயல்படும் வேகம் அல்லது எதிர்பார்ப்பு மாறுவதைக் கவனமின்மையாகப் புரிந்துகொள்ள வாய்ப்பு உண்டு. உறவைப் பற்றிய பெரிய முடிவுக்கு முன் எந்த வாக்கு, எல்லை, பொறுப்பு தொடர்பாக முரண்பாடு வருகிறது என்பதைத் தெளிவுபடுத்துங்கள்.'],
 ['You may become more capable through experiences that require patience with uncertainty. Research, confidential work and careful handling of shared responsibilities can reward depth rather than quick answers.','உடனே பதில் கிடைக்காத சூழலில் பொறுமையாக ஆராயும் அனுபவம் உங்கள் திறனை வளர்க்கலாம். ஆய்வு, ரகசியம் காக்க வேண்டிய பணி, கூட்டு பொறுப்பு போன்றவற்றில் அவசரத்தை விட ஆழ்ந்த கவனம் பயன்படும்.', 'Unclear agreements can create avoidable worry, especially where another person controls part of a shared decision. Ask for the missing information rather than filling the gap with assumptions.','கூட்டு முடிவில் ஒரு பகுதி மற்றவரிடம் இருக்கும்போது தெளிவில்லாத ஒப்பந்தம் கவலையை அதிகரிக்கலாம். தெரியாத விஷயத்தை ஊகித்து முடிவு செய்வதை விட தேவையான தகவலை நேரடியாகக் கேட்பது நல்லது.'],
 ['A teacher, experienced elder or a broader field of study can help you see possibilities beyond your present surroundings. Advice becomes valuable when you test it through your own experience.','ஆசிரியர், அனுபவமுள்ள பெரியவர் அல்லது விரிவான படிப்பு உங்கள் தற்போதைய சூழலுக்கு அப்பால் உள்ள வாய்ப்பைக் காட்டலாம். கிடைக்கும் அறிவுரையை அனுபவத்தில் பயன்படுத்திப் பார்க்கும்போது அதன் பயன் தெளிவாகும்.', 'Your own beliefs and an elder’s expectations may not always agree. Respectful disagreement and a reasoned plan are more useful than following advice unwillingly or rejecting it in anger.','உங்கள் நம்பிக்கையும் பெரியவரின் எதிர்பார்ப்பும் எல்லா நேரமும் ஒன்றாக இருக்க வேண்டியதில்லை. விருப்பமின்றி பின்பற்றுவதற்கும் கோபத்தில் மறுப்பதற்கும் பதிலாக உங்கள் திட்டத்தின் காரணத்தை அமைதியாக விளக்குங்கள்.'],
 ['Your professional standing can grow through work that gives you clear responsibility and lets others see the result. Reliability, judgement and the ability to finish what you undertake may become stronger assets than a title alone.','எந்தப் பொறுப்பு உங்களுடையது, அதன் முடிவு என்ன என்பது தெளிவாக இருக்கும் வேலையில் தொழில் மதிப்பு வளரலாம். பதவிப் பெயரை விட நம்பகத்தன்மை, முடிவெடுக்கும் திறன், எடுத்த வேலையை முடிக்கும் பண்பு உங்களுக்கு பெயர் பெற்றுத் தரக்கூடும்.', 'Responsibility may increase before recognition catches up. If this occurs, discuss authority, workload and the basis of evaluation instead of silently accepting every additional task.','அங்கீகாரம் கிடைப்பதற்கு முன்பே பொறுப்பு அதிகரிக்கலாம். அப்படியானால் எல்லா வேலையையும் அமைதியாக ஏற்றுக்கொள்வதை விட அதிகாரம், பணிச்சுமை, மதிப்பீட்டு முறை ஆகியவற்றை உரிய நேரத்தில் பேசுவது உதவும்.'],
 ['A useful circle of colleagues, friends or returning clients can help effort become visible opportunity. The strongest gains may come from relationships built through dependable contributions rather than frequent introductions.','நம்பகமான நண்பர், சக ஊழியர், மீண்டும் வரும் வாடிக்கையாளர் தொடர்பு உங்கள் முயற்சியை வாய்ப்பாக மாற்றலாம். பலரைச் சந்திப்பதை விட ஏற்கனவே உள்ள தொடர்பில் தொடர்ந்து மதிப்புள்ள பங்களிப்பு செய்வது பயன் தரலாம்.', 'Too many goals or social obligations can spread your time thin. Check which connection produces real cooperation and which merely creates more expectations.','பல இலக்குகளும் சமூகப் பொறுப்புகளும் உங்கள் நேரத்தைப் பிரித்துவிடலாம். எந்தத் தொடர்பு உண்மையான ஒத்துழைப்பைத் தருகிறது, எது எதிர்பார்ப்பை மட்டும் அதிகரிக்கிறது என்பதை கவனியுங்கள்.'],
 ['Quiet work, rest and time away from constant demands can help you regain perspective. Distant connections may be useful when they have a clear purpose and fit your existing responsibilities.','தொடர்ச்சியான வெளிப்புறக் கோரிக்கைகளிலிருந்து சிறிது விலகி அமைதியாக வேலை செய்வதும் ஓய்வெடுப்பதும் தெளிவைத் தரலாம். தொலைதூரத் தொடர்பு உங்கள் தேவைக்கும் பொறுப்புக்கும் பொருந்தும்போது பயனுள்ளதாக அமையலாம்.', 'Unnoticed expenses, unfinished commitments or insufficient rest may gradually reduce your sense of control. Make recurring costs and unfinished tasks visible before starting another major undertaking.','கவனிக்காத செலவு, முடிக்காத பொறுப்பு, போதிய ஓய்வின்மை ஆகியவை படிப்படியாகச் சுமையை அதிகரிக்கலாம். புதிய பெரிய முயற்சிக்கு முன் தொடர்ச்சியான செலவையும் நிலுவைப் பணியையும் பட்டியலிட்டு முடிக்க வழி பாருங்கள்.']
];
const V253_ROUTE=[null,
 ['your own initiative and willingness to be visible','உங்கள் சுயமுயற்சி மற்றும் நேரடிப் பங்களிப்பு'],['family commitments, speech and the resources you retain','குடும்பப் பொறுப்பு, பேச்சு மற்றும் சேர்த்துவைக்கும் வளம்'],['practice, communication and the courage to make the first attempt','பயிற்சி, தொடர்பு மற்றும் முதல் முயற்சியைத் தொடங்கும் துணிவு'],['home stability, education and the support available in private life','வீட்டு அமைதி, கல்வி மற்றும் தனிப்பட்ட வாழ்க்கையில் கிடைக்கும் ஆதரவு'],['learning, judgement and the ability to develop an idea','கற்றல், சிந்தித்து முடிவெடுத்தல் மற்றும் ஒரு கருத்தை வளர்க்கும் திறன்'],['daily service, obligations and the problems you learn to solve','அன்றாடப் பணி, கடமை மற்றும் தீர்க்கக் கற்றுக்கொள்ளும் சிக்கல்கள்'],['partners, clients and agreements with other people','துணைவர், வாடிக்கையாளர் மற்றும் மற்றவருடன் செய்யும் ஒப்பந்தம்'],['shared commitments, research and adaptation when plans change','கூட்டு பொறுப்பு, ஆராய்ச்சி மற்றும் திட்டம் மாறும்போது ஒத்துப்போதல்'],['higher learning, experienced guidance and wider exposure','உயர்கல்வி, அனுபவமுள்ளவரின் வழிகாட்டல் மற்றும் விரிவான தொடர்பு'],['professional responsibility and the reputation earned through work','தொழில் பொறுப்பு மற்றும் உழைப்பால் பெறும் பெயர்'],['networks, collective work and the ability to turn effort into gains','நண்பர் வட்டம், கூட்டு முயற்சி மற்றும் உழைப்பை லாபமாக மாற்றும் திறன்'],['distant connections, private work and careful use of time and resources','தொலைதூரத் தொடர்பு, தனித்த பணி மற்றும் நேரம்–வளத்தைச் சிக்கனமாகப் பயன்படுத்துதல்']
];
const V254_HOUSE_DEPTH={"1": [["Self-confidence and personal decisions", "தன்னம்பிக்கையும் தனிப்பட்ட முடிவுகளும்", "You may trust your judgement more when you can see the result of your own effort. Taking responsibility for a defined task gives that confidence a practical foundation. In a new setting, begin with a contribution you understand well; recognition can then grow from what you actually do.", "உங்கள் முயற்சியின் முடிவை நேரில் பார்க்கும்போது உங்கள் முடிவின்மீது நம்பிக்கை அதிகரிக்கலாம். தெளிவான ஒரு வேலையைப் பொறுப்பேற்று முடிப்பது அந்த நம்பிக்கைக்கு அடித்தளமாகும். புதிய சூழலில் உங்களுக்கு நன்றாகத் தெரிந்த பங்களிப்பை முதலில் செய்யுங்கள்; அதன் தரத்தைப் பார்த்து மற்றவரின் நம்பிக்கையும் வளரலாம்.", "You may spend more energy assessing yourself than the task itself requires. A setback can feel personal even when it arose from circumstances or an unfamiliar method. Separate the part you can improve from the part outside your control; that makes the next attempt less emotionally demanding.", "வேலைக்குத் தேவையானதை விட உங்களையே மதிப்பிடுவதில் அதிக மன ஆற்றல் செலவாகலாம். சூழல் அல்லது பழக்கமில்லாத முறையால் ஏற்பட்ட தடையையும் உங்கள் திறமைக்குக் குறையாக எடுத்துக்கொள்ளலாம். திருத்தக்கூடிய பகுதியையும் உங்கள் கட்டுப்பாட்டிற்கு அப்பாற்பட்ட பகுதியையும் பிரித்தால் அடுத்த முயற்சி மனச்சுமை குறைந்து அமையும்."], ["How you respond to others", "மற்றவரை எதிர்கொள்ளும் விதம்", "Your presence can help a situation move forward when you combine directness with attention to the other person. People may look to you for a clear response or a practical first step. Leaving room for questions helps your confidence come across as reassurance rather than insistence.", "தெளிவாகப் பேசுவதுடன் மற்றவரின் நிலையையும் கவனித்தால் ஒரு விஷயத்தை முன்னெடுக்க உங்கள் பங்கு உதவலாம். சரியான பதில் அல்லது நடைமுறையான முதல் செயலை உங்களிடம் எதிர்பார்க்கலாம். கேள்வி கேட்க இடம் கொடுக்கும்போது உங்கள் உறுதி பிடிவாதமாக அல்லாமல் நம்பிக்கையாகப் புரிந்துகொள்ளப்படும்.", "You may become guarded when you feel misunderstood, or respond before the other person has finished explaining. That can make a small disagreement feel larger than it is. Naming the specific issue and taking time before a final response protects both your position and the relationship.", "தவறாகப் புரிந்துகொள்ளப்பட்டதாக உணர்ந்தால் உங்களைத் தற்காத்துக்கொள்ளும் பேச்சு அதிகரிக்கலாம்; மற்றவர் விளக்கி முடிக்கும் முன்பே பதில் சொல்லவும் தோன்றலாம். அதனால் சிறிய முரண்பாடும் பெரியதாகத் தெரியலாம். குறிப்பிட்ட பிரச்சினையை மட்டும் எடுத்துப் பேசி, இறுதிப் பதிலுக்கு நேரம் எடுத்துக்கொள்வது உதவும்."]], "2": [["Speech and trust within the family", "பேச்சும் குடும்ப நம்பிக்கையும்", "Your words may carry weight when they remain consistent with what you do. Family members can come to rely on an explanation, reassurance or promise from you. Speaking clearly about what is possible helps preserve that trust when different relatives expect different things.", "சொல்வதும் செய்வதும் ஒன்றாக இருக்கும்போது உங்கள் பேச்சிற்கு மதிப்பு உருவாகலாம். உங்கள் விளக்கம், ஆறுதல் அல்லது வாக்குறுதியை குடும்பத்தினர் நம்பத் தொடங்கலாம். பல உறவினர்கள் வெவ்வேறு எதிர்பார்ப்புடன் இருக்கும்போது உங்களால் முடிவதைத் தெளிவாகச் சொல்வது அந்த நம்பிக்கையைப் பாதுகாக்கும்.", "A practical statement about money or responsibility can be heard as criticism if it is said while upset. The recurring issue may be the manner of speaking rather than the underlying intention. Discuss one concern at a time and avoid bringing every earlier disappointment into the same conversation.", "பணம் அல்லது பொறுப்பு பற்றிய நடைமுறைச் சொல்லும் வருத்தத்தில் கூறும்போது குற்றச்சாட்டாகத் தோன்றலாம். பிரச்சினை நோக்கத்தில் இல்லாமல் சொன்ன விதத்தில் இருக்கக்கூடும். ஒரே நேரத்தில் ஒரு விஷயத்தைப் பேசி, பழைய எல்லா வருத்தங்களையும் அதனுடன் சேர்க்காமல் இருப்பது புரிதலை அதிகரிக்கும்."], ["Keeping resources and meeting obligations", "வளத்தைப் பாதுகாப்பதும் கடமையை நிறைவேற்றுவதும்", "A stable reserve can grow through attention to ordinary commitments rather than one exceptional gain. You may find greater peace when household needs, personal spending and help to relatives are distinguishable. A clear limit makes generosity easier to sustain without creating resentment later.", "ஒரு பெரிய லாபத்தை மட்டும் எதிர்பார்ப்பதை விட அன்றாடப் பொறுப்பை கவனிப்பதன் மூலம் கையிருப்பு நிலைபெறலாம். வீட்டுத் தேவை, தனிப்பட்ட செலவு, உறவினருக்கு உதவி ஆகியவற்றைத் தனியாகப் புரிந்துகொண்டால் மனநிம்மதி அதிகரிக்கலாம். தெளிவான வரம்பு இருந்தால் உதவி செய்வதும் பின்னர் வருத்தமின்றித் தொடர முடியும்.", "Resources may feel stretched when unplanned promises accumulate around the same income. The difficulty is not necessarily a lack of earning ability; several people or goals may depend on the same available amount. Make those commitments visible before assuming that the next increase in income will solve everything.", "ஒரே வருமானத்தைச் சுற்றி திட்டமிடாத வாக்குறுதிகள் சேரும்போது பணம் போதவில்லை என்ற உணர்வு வரலாம். அது சம்பாதிக்கும் திறன் இல்லை என்பதல்ல; ஒரே தொகையை பல தேவைகள் சார்ந்திருக்கலாம். அடுத்த வருமான உயர்வு அனைத்தையும் தீர்த்துவிடும் என்று கருதுவதற்கு முன் அந்தப் பொறுப்புகளைத் தெளிவாகப் பாருங்கள்."]], "3": [["Turning effort into a usable skill", "முயற்சியைப் பயன்படும் திறனாக்குதல்", "An ability can become dependable through practice on real tasks. Writing, explaining, handling a tool or following up a request may improve as you use it repeatedly. Keep a visible record of what you finish; it can show progress that is easy to overlook while concentrating on what remains to be learned.", "உண்மையான வேலையில் தொடர்ந்து பயிற்சி செய்யும்போது ஒரு திறன் நம்பகமானதாக மாறலாம். எழுதுதல், விளக்குதல், கருவியைக் கையாளுதல், கேட்ட விஷயத்தை முடித்துக் கொடுத்தல் ஆகியவை பயன்பாட்டால் மேம்படும். முடித்த வேலைகளைப் பதிவு செய்தால் இன்னும் கற்க வேண்டியதை நினைத்து மறந்துபோகும் முன்னேற்றமும் தெரியும்.", "Several interests may compete for the same time, making it hard to carry any one of them far enough. The next useful step is often smaller than the ambition itself: finish a piece of work, ask for feedback and revise it. This gives effort a direction and reduces the urge to start over repeatedly.", "பல ஆர்வங்கள் ஒரே நேரத்தைப் பகிரும்போது எதையும் போதிய அளவு முடிக்க முடியாமல் போகலாம். பெரிய இலக்கிற்கு அடுத்த பயனுள்ள செயல் சிறியதாக இருக்கலாம்: ஒரு வேலையை முடித்து, கருத்தைக் கேட்டு, திருத்திப் பாருங்கள். இதனால் முயற்சிக்கு திசை கிடைத்து மீண்டும் மீண்டும் புதிதாகத் தொடங்கும் நிலை குறையும்."], ["Siblings, close contacts and cooperation", "சகோதரர் தொடர்பும் நெருங்கிய ஒத்துழைப்பும்", "Cooperation with a sibling or familiar contact can be useful when each person knows what is being asked. Information, introductions or a shared practical task may matter more than constant agreement. A relationship remains easier when help can be requested directly without testing the other person’s loyalty.", "என்ன உதவி கேட்கப்படுகிறது என்பது தெளிவாக இருந்தால் சகோதரர் அல்லது பழகியவரின் ஒத்துழைப்பு பயனுள்ளதாக இருக்கலாம். எப்போதும் ஒரே கருத்தில் இருப்பதை விட தகவல், அறிமுகம், சேர்ந்து செய்யும் வேலை உதவியாக அமையலாம். பற்றைச் சோதிப்பதுபோல் இல்லாமல் நேரடியாக உதவி கேட்பது உறவை எளிதாக்கும்.", "Comparison or an old difference may interfere with cooperation even when practical help is available. It helps to separate the present request from the history between you. Agree on what each person can do now, rather than expecting a single act of help to resolve every earlier disappointment.", "பழைய கருத்து வேறுபாடு அல்லது ஒப்பீடு, கிடைக்கக்கூடிய உதவியைக்கூட பயன்படுத்த முடியாமல் செய்யலாம். தற்போதைய தேவையை பழைய உறவு அனுபவத்திலிருந்து பிரித்துப் பார்ப்பது நல்லது. ஒரே உதவி எல்லா பழைய வருத்தத்தையும் தீர்க்க வேண்டும் என்று எதிர்பார்க்காமல் இப்போது யார் என்ன செய்யலாம் என முடிவெடுங்கள்."]], "4": [["Emotional security and family care", "மனப் பாதுகாப்பும் குடும்பப் பராமரிப்பும்", "A reliable home rhythm may allow you to recover from outside demands more easily. Care can be expressed through small dependable actions rather than constant emotional conversation. Knowing who is available, what has been arranged and where you can rest gives the sense of security a practical shape.", "நம்பகமான வீட்டு ஒழுங்கு இருந்தால் வெளிப்புறப் பணிச்சுமையிலிருந்து மீண்டு வருவது சுலபமாகலாம். எப்போதும் உணர்ச்சியைப் பேசுவதை விட தவறாமல் செய்யும் சிறிய செயல்களாலும் அக்கறை வெளிப்படும். யார் உதவுவார், என்ன ஏற்பாடு உள்ளது, எப்போது ஓய்வெடுக்கலாம் என்ற தெளிவு பாதுகாப்பு உணர்வை உருவாக்கும்.", "A comfortable house may not feel peaceful if responsibilities and privacy remain unsettled. You may need quiet while another family member expects conversation or assistance. Discussing those needs before irritation builds can do more for domestic peace than changing the surroundings alone.", "பொறுப்பும் தனியுரிமையும் தெளிவில்லாவிட்டால் வசதியான வீட்டிலும் அமைதி குறையலாம். உங்களுக்கு அமைதி தேவைப்படும் நேரத்தில் மற்றவர் பேச்சையோ உதவியையோ எதிர்பார்க்கலாம். எரிச்சல் அதிகரிக்கும் முன் தேவைகளைப் பேசுவது சுற்றுப்புறத்தை மட்டும் மாற்றுவதை விட வீட்டில் நிம்மதியை வளர்க்கும்."], ["Learning environment and settlement", "கற்கும் சூழலும் வசிப்பிட நிலைத்தன்மையும்", "Study or focused work can benefit from an organised place and a predictable period without interruption. A home decision becomes useful when it supports the life you actually lead. Consider access to work, learning and family support together so that outward improvement also makes everyday life easier.", "இடையூறில்லாத நேரமும் ஒழுங்கான இடமும் இருந்தால் படிப்பு அல்லது கவனமான வேலை மேம்படலாம். நீங்கள் உண்மையில் வாழும் வாழ்க்கைக்கு உதவும்போது வீடு தொடர்பான முடிவு பயன் தரும். வேலை, கல்வி, குடும்ப உதவி ஆகியவற்றைச் சேர்த்துப் பார்த்தால் வெளிப்புற முன்னேற்றத்துடன் அன்றாட வசதியும் அதிகரிக்கும்.", "A change of place can disturb concentration before its benefits become clear. If study or work is interrupted, first examine travel time, noise, care duties and the availability of a suitable space. Avoid interpreting a difficult environment as proof that you lack ability or cannot settle anywhere.", "இடமாற்றத்தின் பலன் தெரியுமுன் கவனம் சிதறக்கூடும். படிப்பு அல்லது வேலை தடைப்பட்டால் பயண நேரம், சத்தம், பராமரிப்புப் பொறுப்பு, ஏற்ற இடம் ஆகியவற்றை முதலில் பாருங்கள். சிரமமான சூழலை உங்கள் திறமைக் குறைவு அல்லது எங்கும் நிலைபெற முடியாது என்பதற்கான அடையாளமாக எடுத்துக்கொள்ள வேண்டாம்."]], "5": [["Understanding, judgement and creativity", "புரிதல், தீர்மானம் மற்றும் படைப்பாற்றல்", "You may learn more deeply by connecting ideas rather than memorising them in isolation. Explaining a concept, planning a small project or developing a creative work can make that ability visible. Leave room for revision; the first version need not carry the whole weight of proving your talent.", "தனித்தனியாக மனப்பாடம் செய்வதை விட கருத்துகளை இணைத்துப் புரியும்போது ஆழமாகக் கற்கலாம். ஒரு கருத்தை விளக்குதல், சிறு திட்டம் அமைத்தல், படைப்பை உருவாக்குதல் ஆகியவற்றில் அந்தத் திறன் தெரியலாம். முதல் முயற்சியே முழுத் திறமையையும் நிரூபிக்க வேண்டும் என்று நினைக்காமல் திருத்தத்திற்கு இடம் கொடுங்கள்.", "A wish to get the answer right may slow experimentation or make criticism harder to accept. Distinguish a judgement about one piece of work from a judgement about your ability. Trying a smaller version first can preserve curiosity while making errors easier to understand and correct.", "சரியாகவே செய்ய வேண்டும் என்ற எதிர்பார்ப்பு புதிய முயற்சியைத் தாமதப்படுத்தலாம் அல்லது விமர்சனத்தை ஏற்கச் சிரமமாக்கலாம். ஒரு வேலை பற்றிய கருத்தையும் உங்கள் முழுத் திறமை பற்றிய தீர்ப்பையும் பிரித்துப் பாருங்கள். சிறிய வடிவில் முதலில் முயல்வது ஆர்வத்தைப் பாதுகாத்து பிழையைத் திருத்த உதவும்."], ["Care, mentoring and expectations", "பராமரிப்பு, வழிகாட்டல் மற்றும் எதிர்பார்ப்புகள்", "A patient approach can help you guide someone without taking over every decision. Whether this concerns a learner, a younger relative or your own creative work, progress is easier to see when the next step is suited to the person’s stage. Encouragement becomes more useful when it names a specific improvement.", "ஒவ்வொரு முடிவையும் நீங்களே எடுத்துக்கொள்ளாமல் மற்றவரை வழிநடத்த பொறுமை உதவும். மாணவர், இளைய உறவினர் அல்லது உங்கள் சொந்தப் படைப்பு என எதுவாக இருந்தாலும் அடுத்த செயல் தற்போதைய நிலைக்கு ஏற்றதாக இருந்தால் முன்னேற்றம் தெரியும். குறிப்பிட்ட வளர்ச்சியைச் சுட்டிப் பாராட்டுவது அதிக பயன் தரும்.", "Strong expectations can unintentionally turn care into pressure. A child, learner or family member may need a different pace from the one you imagined. Make room for that difference and keep family planning separate from claims that a chart can establish fertility or guarantee a child-related outcome.", "அதிக எதிர்பார்ப்பு அக்கறையையே அழுத்தமாக மாற்றக்கூடும். குழந்தை, மாணவர் அல்லது குடும்பத்தினருக்கு நீங்கள் நினைத்ததை விட வேறு வேகம் தேவைப்படலாம். அந்த வேறுபாட்டிற்கு இடம் கொடுங்கள்; குடும்பத் திட்டமிடலை ஜாதகம் கருத்தரிப்பை உறுதி செய்யும் என்ற எண்ணத்துடன் இணைக்க வேண்டாம்."]], "6": [["Service, workload and useful responsibility", "பணி, சுமை மற்றும் பயன்படும் பொறுப்பு", "You may earn trust through your willingness to deal with the unfinished or inconvenient part of a task. This strength is more sustainable when the work has a clear boundary and a recognised end. Once a process works, sharing it with others can prevent every problem from returning to you.", "வேலையில் முடிக்கப்படாத அல்லது சிரமமான பகுதியை எடுத்துச் செய்வதன் மூலம் நம்பிக்கை பெறலாம். அந்த வேலைக்கு தெளிவான எல்லையும் முடிவும் இருந்தால் இந்தத் திறன் நீடிக்கும். ஒரு முறை சரியாக அமைந்த பிறகு அதை மற்றவருக்கும் பகிர்வது ஒவ்வொரு சிக்கலும் உங்களிடமே திரும்பி வருவதைத் தவிர்க்கும்.", "Repeated small requests can consume the time intended for your main work. The difficulty may come from unclear ownership rather than the size of any one task. Clarify which requests are yours to handle and which need to be shared, scheduled or returned to the person responsible.", "சிறுசிறு கோரிக்கைகள் தொடர்ந்து வந்தால் முக்கிய வேலைக்கான நேரம் குறையலாம். ஒரு வேலையின் அளவை விட அதை யார் கவனிக்க வேண்டும் என்ற தெளிவின்மையே சிக்கலாக இருக்கலாம். நீங்கள் செய்ய வேண்டியது, பகிர வேண்டியது, நேரம் ஒதுக்க வேண்டியது ஆகியவற்றைப் பிரித்துக் கொள்ளுங்கள்."], ["Competition and resolving disagreement", "போட்டியும் கருத்து வேறுபாட்டைத் தீர்ப்பதும்", "Preparation and a record of completed work may help you respond to comparison with greater composure. You do not have to answer every challenge immediately. Choosing the issue that matters allows effort to remain useful instead of being spent on proving a point in every discussion.", "தயாரிப்பும் முடித்த வேலைகளின் பதிவும் இருந்தால் ஒப்பீட்டை அமைதியாக எதிர்கொள்ளலாம். ஒவ்வொரு சவாலுக்கும் உடனே பதில் சொல்ல வேண்டியதில்லை. முக்கியமான விஷயத்தைத் தேர்ந்தெடுத்தால் எல்லா உரையாடலிலும் உங்களை நிரூபிக்க முயல்வதற்குப் பதிலாக உழைப்பு பயனுள்ள திசையில் இருக்கும்.", "An unresolved disagreement can occupy more attention than the practical issue warrants. Separate facts, assumptions and the action you want from the other person. Where documents or formal responsibilities are involved, the next step should depend on verified information and appropriate professional advice.", "தீராத கருத்து வேறுபாடு தேவைக்கு அதிகமாக மனதை ஆக்கிரமிக்கலாம். உண்மை, ஊகம், மற்றவரிடம் நீங்கள் எதிர்பார்க்கும் செயல் ஆகியவற்றைப் பிரித்துப் பாருங்கள். ஆவணம் அல்லது முறையான பொறுப்பு தொடர்பான விஷயத்தில் உறுதியான தகவலையும் பொருத்தமான நிபுணர் ஆலோசனையையும் வைத்து அடுத்த செயலைத் தீர்மானிக்க வேண்டும்."]], "7": [["Partnership and mutual expectations", "துணை உறவும் பரஸ்பர எதிர்பார்ப்புகளும்", "Cooperation may become a source of strength when each person retains a clear voice. A partner can bring a perspective or skill that complements your own. Everyday agreements about time, attention and responsibility help that difference become useful rather than a reason to compete.", "இருவருக்கும் தங்கள் கருத்தைச் சொல்ல இடம் இருந்தால் ஒத்துழைப்பு பலமாக மாறலாம். உங்கள் திறனுக்கு துணையாக மற்றவர் வேறு பார்வையையோ திறனையோ கொண்டு வரலாம். நேரம், கவனம், பொறுப்பு பற்றிய அன்றாட உடன்பாடுகள் அந்த வேறுபாட்டை போட்டியாக இல்லாமல் பயனுள்ளதாக மாற்றும்.", "Unspoken expectations may cause disappointment even when both people intend well. One person may look for reassurance while the other offers a practical solution. Explaining the need before judging the response makes it easier to see whether the difficulty is affection, timing or a mismatch in expectations.", "இருவருக்கும் நல்ல நோக்கம் இருந்தாலும் சொல்லப்படாத எதிர்பார்ப்பு ஏமாற்றத்தை ஏற்படுத்தலாம். ஒருவருக்கு ஆறுதல் தேவைப்படும் போது மற்றவர் நடைமுறைத் தீர்வு சொல்லலாம். பதிலை மதிப்பிடுவதற்கு முன் தேவையை விளக்கினால் சிக்கல் அன்பிலா, நேரத்திலா, எதிர்பார்ப்பிலா என்பது தெளிவாகும்."], ["Clients, agreements and shared decisions", "வாடிக்கையாளர், ஒப்பந்தம் மற்றும் கூட்டு முடிவுகள்", "Direct discussion can make a business or working relationship more reliable. Clearly stating the task, the time involved and what will be delivered reduces later ambiguity. Goodwill then supports an understood agreement rather than being asked to replace one.", "நேரடியாகப் பேசுவது வணிக அல்லது பணித் தொடர்பை நம்பகமாக்கலாம். செய்யும் வேலை, தேவைப்படும் நேரம், கொடுக்கப்படும் முடிவு ஆகியவற்றைத் தெளிவுபடுத்தினால் பின்னர் குழப்பம் குறையும். புரிந்துகொண்ட ஒப்பந்தத்திற்கு நல்லெண்ணம் துணையாக இருக்கும்; ஒப்பந்தத்திற்குப் பதிலாக இருக்க வேண்டியதில்லை.", "A promise may be interpreted differently by the people involved. Before concluding that someone has let you down, check whether scope, timing and responsibilities were actually shared clearly. Reaching a specific new agreement can be more useful than reopening the whole relationship as a dispute.", "ஒரே வாக்குறுதியை இருவரும் வேறு விதமாகப் புரிந்துகொள்ளலாம். மற்றவர் ஏமாற்றிவிட்டார் என்று முடிவு செய்வதற்கு முன் வேலை வரம்பு, நேரம், பொறுப்பு ஆகியவை தெளிவாகப் பகிரப்பட்டதா என்று பாருங்கள். உறவு முழுவதையும் பிரச்சினையாக்காமல் குறிப்பிட்ட புதிய உடன்பாடு ஏற்படுத்துவது உதவும்."]], "8": [["Responding when a plan changes", "திட்டம் மாறும்போது மீண்டும் நிலைபெறுதல்", "You may be able to work through uncertainty by finding out what has changed and what still remains usable. A careful review can turn an interruption into a more realistic plan. The strength lies in rebuilding with better information rather than trying to recover the exact earlier arrangement.", "எது மாறிவிட்டது, எது இன்னும் பயன்படும் என்பதை அறிந்தால் தெளிவில்லாத சூழலைக் கையாளலாம். கவனமான மறுபரிசீலனை ஒரு தடையை நடைமுறைக்கு ஏற்ற திட்டமாக மாற்றலாம். பழைய அமைப்பை அப்படியே மீட்பதை விட புதிய தகவலுடன் மீண்டும் அமைப்பதில் பலம் இருக்கலாம்.", "An unexpected change may create a wish to regain control before the facts are clear. Avoid treating every uncertainty as evidence of a hidden problem. Gather what can be verified, identify the next manageable step and leave larger conclusions until enough information is available.", "எதிர்பாராத மாற்றம் ஏற்பட்டால் உண்மை தெளிவாகுமுன் கட்டுப்பாட்டை மீட்டெடுக்க வேண்டும் என்று தோன்றலாம். ஒவ்வொரு குழப்பத்தையும் மறைந்த பிரச்சினைக்கான அடையாளமாகக் கருத வேண்டாம். உறுதிப்படுத்தக்கூடிய தகவலைப் பெற்று அடுத்த சிறிய செயலைத் தீர்மானித்து, பெரிய முடிவிற்கு போதிய விவரம் வரும்வரை இடம் கொடுங்கள்."], ["Shared resources and private concerns", "கூட்டு வளமும் தனிப்பட்ட கவலைகளும்", "Trust grows when a shared commitment is understood by everyone who carries it. Openness about documents, contributions and changes can reduce the need for repeated reassurance. Respect for privacy can coexist with clear information about matters whose consequences affect both people.", "கூட்டு பொறுப்பை ஏற்ற அனைவருக்கும் அது புரிந்திருக்கும்போது நம்பிக்கை வளர்கிறது. ஆவணம், பங்களிப்பு, மாற்றம் ஆகியவற்றில் வெளிப்படைத்தன்மை இருந்தால் அடிக்கடி உறுதி கேட்க வேண்டிய அவசியம் குறையும். தனியுரிமையை மதிப்பதுடன் இருவரையும் பாதிக்கும் விஷயத்தில் தெளிவையும் வைத்திருக்கலாம்.", "A lack of information can become more troubling than the actual obligation. A person may hesitate to ask because the topic feels private or sensitive. A calm, specific conversation about what must be known is more useful than allowing silence to turn into suspicion.", "உண்மையான பொறுப்பை விட தகவல் தெரியாத நிலையே அதிகக் கவலை தரலாம். தனிப்பட்ட விஷயம் என்பதால் கேட்கத் தயக்கமும் இருக்கலாம். மௌனம் சந்தேகமாக மாறுவதற்கு முன் என்ன தகவல் தேவை என்பதை அமைதியாகவும் குறிப்பாகவும் பேசுவது உதவும்."]], "9": [["Learning from elders and experience", "பெரியவரிடமிருந்தும் அனுபவத்திலிருந்தும் கற்றல்", "Advice may open a useful path when it helps you see a choice more clearly. An elder or teacher need not agree with every decision to offer something valuable. Test the guidance against your situation and keep the part that improves your understanding or preparation.", "ஒரு தேர்வைத் தெளிவாகப் பார்க்க உதவும்போது அறிவுரை பயனுள்ள பாதையைத் திறக்கலாம். எல்லா முடிவையும் பெரியவர் அல்லது ஆசிரியர் ஏற்றுக்கொள்ளாவிட்டாலும் பயனுள்ள கருத்தைக் கொடுக்க முடியும். உங்கள் சூழலுடன் ஒப்பிட்டுப் பார்த்து புரிதலையும் தயாரிப்பையும் மேம்படுத்தும் பகுதியைப் பயன்படுத்துங்கள்.", "Differences over values or life direction may make guidance feel like pressure. You can acknowledge the concern without immediately accepting the proposed choice. Explain the reasons for your plan and identify where more information is needed before either side treats disagreement as disrespect.", "மதிப்பு அல்லது வாழ்க்கைத் திசையில் வேறுபாடு இருந்தால் வழிகாட்டலே அழுத்தமாகத் தோன்றலாம். சொல்லப்பட்ட தேர்வை உடனே ஏற்காமல் அக்கறையை ஏற்றுக்கொள்ளலாம். உங்கள் திட்டத்தின் காரணத்தையும் இன்னும் என்ன தகவல் தேவை என்பதையும் விளக்குவது கருத்து வேறுபாட்டை மரியாதைக் குறைவாக மாறாமல் காக்கும்."], ["Opportunity through wider exposure", "விரிவான அனுபவம் தரும் வாய்ப்பு", "A wider course of study, a journey or contact with a different way of working may help you recognise an option close to your abilities. Its value becomes clearer when you bring something useful back into your ordinary work. Exposure is a beginning; application gives it lasting meaning.", "விரிவான படிப்பு, பயணம் அல்லது வேறு வேலை முறையுடன் தொடர்பு உங்கள் திறனுக்கு ஏற்ற வாய்ப்பைக் காட்டலாம். அதிலிருந்து கற்றதை அன்றாட வேலையில் பயன்படுத்தும்போது பயன் தெளிவாகும். புதிய அனுபவம் தொடக்கமாகவும் அதன் பயன்பாடு நீடித்த பலனாகவும் அமையும்.", "A distant or prestigious option may seem attractive before its day-to-day demands are understood. Compare what you would actually learn or do with the effort involved in reaching it. A familiar option with a clear purpose may sometimes be more useful than a larger promise with no practical route.", "தொலைதூர அல்லது புகழ்பெற்ற வாய்ப்பின் அன்றாடத் தேவை தெரியுமுன் அது கவரக்கூடும். அங்கு உண்மையில் என்ன கற்பீர்கள் அல்லது செய்வீர்கள் என்பதை அதற்கான முயற்சியுடன் ஒப்பிடுங்கள். நடைமுறை வழியில்லாத பெரிய வாக்குறுதியை விட தெளிவான நோக்கமுள்ள பழகிய வாய்ப்பு சில நேரம் அதிக பயன் தரலாம்."]], "10": [["Responsibility and recognition at work", "தொழில் பொறுப்பும் அங்கீகாரமும்", "Your contribution can become more visible when a task has a clear result and someone relies on your judgement. Recognition may follow repeated reliability before it appears as a new title. Keep track of the decisions and improvements you are responsible for so that the substance of your work is understood.", "வேலையின் முடிவு தெளிவாகவும் உங்கள் தீர்மானத்தை ஒருவர் நம்பும் நிலையிலும் இருந்தால் பங்களிப்பு வெளிப்படலாம். புதிய பதவி கிடைப்பதற்கு முன்பே தொடர்ந்து நம்பகமாகச் செய்வதன் மூலம் அங்கீகாரம் உருவாகலாம். நீங்கள் எடுத்த முடிவுகளையும் செய்த மேம்பாடுகளையும் பதிவு செய்தால் உழைப்பின் உண்மையான மதிப்பு புரியும்.", "More responsibility may arrive without the authority or assistance needed to carry it well. That can create frustration even if the work itself suits you. Clarify priorities and the basis of evaluation before assuming that taking on everything will necessarily bring recognition.", "பொறுப்பு அதிகரித்தும் அதைச் செய்ய வேண்டிய அதிகாரம் அல்லது உதவி கிடைக்காமல் இருக்கலாம். வேலை உங்களுக்கு ஏற்றதாக இருந்தாலும் இதனால் வருத்தம் உருவாகலாம். எல்லாவற்றையும் ஏற்றால் அங்கீகாரம் கிடைக்கும் என்று கருதுவதற்கு முன் முன்னுரிமை மற்றும் மதிப்பீட்டு முறையைத் தெளிவுபடுத்துங்கள்."], ["Choosing a direction that can last", "நீடிக்கக்கூடிய தொழில் திசையைத் தேர்வு செய்தல்", "A suitable direction allows your abilities to become more useful as experience accumulates. Look for the part of work in which you solve problems, explain clearly or coordinate responsibility with increasing confidence. That recurring contribution may tell you more about professional fit than a single impressive opportunity.", "அனுபவம் சேரும்போது உங்கள் திறன் மேலும் பயன்படும் திசை தொழிலிற்கு ஏற்றதாக அமையும். சிக்கலைத் தீர்த்தல், தெளிவாக விளக்குதல், பொறுப்பை ஒருங்கிணைத்தல் ஆகியவற்றில் எதை நம்பிக்கையுடன் செய்கிறீர்கள் என்று பாருங்கள். ஒரு கவர்ச்சியான வாய்ப்பை விட தொடர்ந்து வழங்கும் பங்களிப்பே தொழில் பொருத்தத்தைத் தெளிவாக்கலாம்.", "The desire to escape current pressure can make any alternative seem better. Separate dissatisfaction with a manager, schedule or workload from dissatisfaction with the whole field. A precise understanding of what needs to change helps prevent the same difficulty from following you into a new setting.", "தற்போதைய அழுத்தத்திலிருந்து விலக வேண்டும் என்ற எண்ணத்தில் எந்த மாற்றமும் சிறந்ததாகத் தோன்றலாம். மேலாளர், நேரம், சுமை பற்றிய அதிருப்தியையும் முழுத் துறை பற்றிய அதிருப்தியையும் பிரித்துப் பாருங்கள். என்ன மாற வேண்டும் என்பது தெளிவாக இருந்தால் அதே சிக்கல் புதிய இடத்திலும் தொடர்வதைத் தவிர்க்கலாம்."]], "11": [["Useful networks and returning opportunities", "பயனுள்ள தொடர்பும் மீண்டும் வரும் வாய்ப்பும்", "A familiar professional or social circle can become valuable through repeated, reliable exchanges. You may benefit from being known for a particular contribution rather than trying to be useful to everyone. Returning opportunities often reveal where earlier effort has built genuine trust.", "தொடர்ந்து நம்பகமாகப் பழகுவதன் மூலம் பழகிய தொழில் அல்லது சமூக வட்டம் பயனுள்ளதாக மாறலாம். எல்லாருக்கும் எல்லாவிதமாக உதவ முயல்வதை விட குறிப்பிட்ட பங்களிப்பிற்காக அறியப்படுவது உதவும். மீண்டும் வரும் வாய்ப்புகள் முன்பு செய்த முயற்சி எங்கு நம்பிக்கையை உருவாக்கியுள்ளது என்பதைக் காட்டும்.", "A large circle can bring expectations as well as help. Some contacts may ask for time without offering real cooperation in return. Notice which relationships support a shared purpose and which keep you occupied without moving an important goal forward.", "பெரிய தொடர்பு வட்டம் உதவியுடன் எதிர்பார்ப்பையும் கொண்டு வரலாம். சிலர் உண்மையான ஒத்துழைப்பு இல்லாமல் நேரத்தை மட்டும் கேட்கலாம். எந்தத் தொடர்பு கூட்டு நோக்கிற்கு உதவுகிறது, எது முக்கிய இலக்கை முன்னெடுக்காமல் வேலை வாங்குகிறது என்று கவனியுங்கள்."], ["Fulfilment and long-term goals", "மனநிறைவும் நீண்டகால இலக்கும்", "A goal becomes more satisfying when progress can be recognised in stages. The result may include a stronger network, dependable work or a useful role in a group, not only a financial gain. Decide what completion would look like so that each achievement does not immediately disappear behind the next expectation.", "முன்னேற்றத்தைப் படிப்படியாக அறிந்துகொள்ளும்போது இலக்கு மனநிறைவைத் தரும். பண லாபம் மட்டுமல்லாமல் உறுதியான தொடர்பு, தொடர்ந்து வரும் வேலை, குழுவில் பயன்படும் பங்கு ஆகியவையும் பலனாக இருக்கலாம். முடிவு என்னவாக இருக்க வேண்டும் என்பதைத் தீர்மானித்தால் ஒவ்வொரு சாதனையும் அடுத்த எதிர்பார்ப்பில் மறையாது.", "Comparing your progress with others can make genuine gains feel insufficient. Too many goals may also compete for the same resources. Choose which result matters most in the present stage and allow other ambitions to wait without treating that order as failure.", "மற்றவருடன் ஒப்பிடும்போது உண்மையான முன்னேற்றமும் போதவில்லை என்று தோன்றலாம். பல இலக்குகள் ஒரே வளத்தைப் பகிரவும் நேரலாம். தற்போதைய கட்டத்தில் எந்த முடிவு முக்கியம் என்பதைத் தேர்ந்தெடுத்து மற்ற ஆசைகளை வரிசைப்படுத்துவது தோல்வி அல்ல என்பதை ஏற்றுக்கொள்ளுங்கள்."]], "12": [["Rest, privacy and restoring attention", "ஓய்வு, தனிநேரம் மற்றும் கவனத்தை மீட்டெடுத்தல்", "Time away from constant demands can help you return to work and relationships with greater clarity. Quiet does not have to mean isolation; it can be a planned interval that restores attention. A routine that includes genuine rest makes private time easier to protect without withdrawing from important responsibilities.", "தொடர்ச்சியான கோரிக்கைகளிலிருந்து சிறிது இடைவெளி கிடைத்தால் வேலையையும் உறவையும் தெளிவாக அணுகலாம். அமைதி என்பது தனிமைப்படுதல் அல்ல; கவனத்தை மீட்கும் திட்டமிட்ட நேரமாக இருக்கலாம். உண்மையான ஓய்வு உள்ள ஒழுங்கு முக்கியப் பொறுப்பிலிருந்து விலகாமல் தனிநேரத்தைப் பாதுகாக்க உதவும்.", "Unfinished tasks or worry may occupy the time meant for rest. Being physically away from work does not always mean attention has been released from it. A clear stopping point and a note of the next task can make it easier to set a concern aside until it can actually be addressed.", "முடிக்காத வேலை அல்லது கவலை ஓய்விற்கான நேரத்தையும் எடுத்துக்கொள்ளலாம். வேலையிலிருந்து உடலால் விலகியிருந்தாலும் மனம் அதிலேயே இருக்கலாம். எங்கு நிறுத்துகிறீர்கள், அடுத்து என்ன செய்ய வேண்டும் என்ற குறிப்பு இருந்தால் செய்ய முடியாத நேரத்தில் அதையே நினைத்துக் கொண்டிருப்பது குறையலாம்."], ["Distant work and the cost of commitment", "தொலைதூரப் பணியும் பொறுப்பிற்கான செலவும்", "A distant connection or private role can be useful when its purpose is clear. The benefit may come through research, preparation or work that others do not immediately see. Keep the effort proportionate to what the arrangement makes possible, so background work supports a meaningful result.", "நோக்கம் தெளிவாக இருந்தால் தொலைதூரத் தொடர்பு அல்லது பின்னணிப் பணி பயன்படும். ஆய்வு, தயாரிப்பு, உடனே மற்றவருக்குத் தெரியாத உழைப்பு ஆகியவற்றின் மூலம் பலன் வரலாம். அந்த ஏற்பாட்டால் கிடைக்கும் பயனுக்கு ஏற்ற அளவில் முயற்சி இருந்தால் பின்னணி வேலையும் பொருள் உள்ள முடிவிற்கு உதவும்.", "An arrangement that looks attractive from a distance may consume more time, money or family support than expected. Understand recurring commitments before deciding that the distance itself promises progress. The right arrangement should remain workable after the initial excitement has passed.", "தொலைவில் இருந்து கவரும் ஏற்பாடு எதிர்பார்த்ததை விட நேரம், பணம் அல்லது குடும்ப உதவியைத் தேவைப்படுத்தலாம். தூரம் இருப்பதே முன்னேற்றம் தரும் என்று கருதுவதற்கு முன் தொடர்ச்சியான கடமைகளைப் புரிந்துகொள்ளுங்கள். ஆரம்ப ஆர்வம் குறைந்த பிறகும் சமாளிக்கக்கூடிய ஏற்பாடே பொருத்தமானது."]]};
const V255_DOMAIN_DEPTH={"career": [["How your work earns trust", "உங்கள் உழைப்புக்கு மதிப்பு உருவாகும் விதம்", "In a career reading, responsibility and recognition need to be considered separately. You might be trusted with difficult work before your title or position changes. If that happens, the useful question is whether the additional work gives you a skill, authority or visible result that can support your next step. A busy period becomes meaningful progress when others can identify what improved because of your contribution.", "தொழிலைப் பார்க்கும்போது பொறுப்பு அதிகரிப்பதையும் அங்கீகாரம் கிடைப்பதையும் தனித்தனியாகப் புரிந்துகொள்ள வேண்டும். பதவி மாறுவதற்கு முன்பே சிரமமான வேலையை உங்களை நம்பி ஒப்படைக்கலாம். அப்போது கூடும் வேலை புதிய திறனையோ முடிவெடுக்கும் அதிகாரத்தையோ பிறர் கவனிக்கும் முடிவையோ தருகிறதா என்று பாருங்கள். உங்கள் பங்களிப்பால் என்ன முன்னேற்றம் ஏற்பட்டது என்பது தெளிவாகத் தெரிந்தால்தான் அதிக உழைப்பு அடுத்த நிலைக்குச் செல்லும் ஆதாரமாக மாறும்."], ["Choosing the next professional step", "அடுத்த தொழில் நிலையைத் தேர்ந்தெடுத்தல்", "Separate dissatisfaction with a particular workplace from dissatisfaction with the work itself. The same ability may find a better expression under a different manager, with a clearer role or through an independent assignment. Read the house connections below as clues to the circumstances in which your effort can become useful. They do not require you to discard experience that is still valuable.", "ஒரு நிறுவனத்தின் சூழல் பிடிக்காததையும் செய்யும் தொழிலே பிடிக்காததையும் ஒன்றாக எடுத்துக்கொள்ள வேண்டாம். அதே திறன் வேறு மேலாளர், தெளிவான பொறுப்பு அல்லது தனியாக ஏற்றுச் செய்யும் பணியில் சிறப்பாக வெளிப்படலாம். கீழே வரும் பாவத் தொடர்புகள் உங்கள் முயற்சி எந்தச் சூழலில் பயன்படலாம் என்பதற்கான விளக்கங்கள். ஏற்கனவே பெற்ற அனுபவம் பயனுள்ளதாக இருந்தால் அதை முழுவதும் விட்டுவிட்டு ஆரம்பிக்க வேண்டும் என்ற பொருள் இல்லை."]], "jobchange": [["What a change needs to improve", "வேலை மாற்றம் எதைச் சரிசெய்ய வேண்டும்", "A change becomes worthwhile when it resolves a specific difficulty. That might be an unclear role, a long daily journey, limited learning or an arrangement that leaves too little room for family. First identify the concern that is making you consider leaving. Without that clarity, an attractive new offer can recreate the same dissatisfaction in a different setting.", "வேலை மாற்றம் ஒரு குறிப்பிட்ட குறையைத் தீர்க்கும்போதுதான் அதன் பயன் தெரியும். பொறுப்பில் தெளிவின்மை, நீண்ட அன்றாடப் பயணம், கற்றுக்கொள்ள வாய்ப்பின்மை அல்லது குடும்பத்திற்கான நேரக் குறைவு அதற்குக் காரணமாக இருக்கலாம். வெளியேற நினைக்க வைக்கும் முக்கியமான குறை எது என்பதை முதலில் பிரித்துப் பாருங்கள். அந்தத் தெளிவு இல்லையெனில் நல்லதாகத் தோன்றும் புதிய வாய்ப்பிலும் பழைய மனக்குறை வேறு வடிவில் தொடரலாம்."], ["The transition after joining", "புதிய இடத்தில் நிலைபெறும் காலம்", "An opening and a settled position are two different stages. After a move, you still need to understand the people, expectations and methods of the new place. Temporary uncertainty during that adjustment does not by itself mean the decision was mistaken. Compare what was promised with what is actually developing, and give attention to the part of the transition that remains within your control.", "வாய்ப்பு கிடைப்பதும் புதிய இடத்தில் நிலைபெறுவதும் இரண்டு கட்டங்கள். மாறிய பிறகு அங்குள்ள மனிதர்கள், எதிர்பார்ப்புகள், வேலை முறைகள் ஆகியவற்றைப் புரிந்துகொள்ள நேரம் தேவைப்படும். அந்த இடைக்காலத் தடுமாற்றத்தை மட்டும் வைத்து முடிவு தவறு என்று கருத வேண்டாம். சொல்லப்பட்ட வாய்ப்புக்கும் நடைமுறையில் உருவாகும் நிலைக்கும் உள்ள வேறுபாட்டைக் கவனித்தால் எந்தப் பகுதியில் கூடுதல் முயற்சி தேவை என்பது தெரியும்."]], "skills": [["From understanding to useful ability", "புரிந்த அறிவு பயன்படும் திறனாக மாறுதல்", "Knowing how something works is the beginning; being able to explain it, repeat it and adapt it to another person's need makes it a usable skill. A course or certificate can help, but the more revealing sign is whether you can finish a task without depending on the same help each time. This distinction lets you recognise gradual improvement even when outside recognition is slow.", "ஒரு விஷயம் எப்படி இயங்குகிறது என்று புரிந்துகொள்வது ஆரம்பம். அதை விளக்கிச் சொல்லவும் மீண்டும் செய்து காட்டவும் மற்றவரின் தேவைக்கு ஏற்ப மாற்றிப் பயன்படுத்தவும் முடிந்தால்தான் பயன்படும் திறனாகிறது. பயிற்சிச் சான்றிதழ் உதவலாம்; ஆனால் ஒவ்வொரு முறையும் அதே உதவியை எதிர்பார்க்காமல் வேலையை முடிக்கிறீர்களா என்பதே வளர்ச்சியின் தெளிவான அடையாளம். வெளிப்புற அங்கீகாரம் தாமதமானாலும் இந்த மாற்றத்தை வைத்து முன்னேற்றத்தை அறியலாம்."], ["Communicating what you know", "தெரிந்ததை மற்றவர் புரிந்துகொள்ளச் செய்தல்", "A difference in communication is not always a difference in intelligence. You may understand the subject but choose a level of detail that the listener cannot yet use. Notice whether the other person needs an explanation, an example or a clear decision. Adjusting the form of your message can make the same knowledge more effective without changing its substance.", "தொடர்பு முறையில் ஏற்படும் சிக்கலை அறிவுக் குறையாக எடுத்துக்கொள்ள வேண்டாம். விஷயம் நன்றாகத் தெரிந்திருந்தாலும் கேட்பவருக்குத் தேவையில்லாத அளவு விவரமாகச் சொல்லலாம். அவருக்கு விளக்கம் வேண்டுமா, எடுத்துக்காட்டு வேண்டுமா, முடிவு மட்டும் வேண்டுமா என்பதை அறிந்து பேசுங்கள். சொல்லும் வடிவத்தை மாற்றுவதால் ஏற்கனவே உள்ள அறிவே மேலும் பயனுள்ளதாக அமையும்."]], "turning": [["Recognising a real turning point", "உண்மையான திருப்பத்தை அடையாளம் காணுதல்", "A turning point need not arrive as a dramatic event. It can begin when a familiar arrangement stops serving an important need and you become willing to consider another way. Distinguish a passing reaction from a change that remains meaningful after the immediate emotion settles. The lasting change usually involves a different responsibility, priority or method, not simply a strong feeling about the future.", "வாழ்க்கைத் திருப்பம் எப்போதும் பெரிய நிகழ்வாக மட்டுமே வருவதில்லை. பழகிய அமைப்பு முக்கியமான தேவையை நிறைவேற்றவில்லை என்று உணர்ந்து வேறு வழியைப் பார்க்கத் தயாராவதும் அதன் ஆரம்பமாக இருக்கலாம். உடனடி உணர்ச்சியால் வரும் முடிவையும் மனம் அமைந்த பிறகும் பொருள் உள்ளதாகத் தோன்றும் மாற்றத்தையும் பிரித்துப் பாருங்கள். நிலையான திருப்பத்தில் பொறுப்பு, முன்னுரிமை அல்லது செயல்முறையில் உண்மையான மாற்றம் இருக்கும்."], ["What to carry into the next stage", "அடுத்த கட்டத்திற்கு எடுத்துச் செல்ல வேண்டியது", "Reconsidering a direction does not make every earlier effort wasted. Experience, reliable relationships and a skill that has already been tested may remain useful even when the original plan changes. Decide what belongs to the old arrangement and what can travel with you. That separation makes a transition less overwhelming and gives the next stage a stronger starting point.", "பாதையை மறுபரிசீலனை செய்வதால் முன்பு செய்த அனைத்தும் வீணாகிவிடுவதில்லை. பழைய திட்டம் மாறினாலும் அனுபவம், நம்பகமான தொடர்பு, செய்து பார்த்துத் தெரிந்த திறன் ஆகியவை பயன்படும். பழைய அமைப்போடு முடிவது எது, அடுத்த கட்டத்திற்கும் எடுத்துச் செல்லக்கூடியது எது என்று பிரித்துப் பாருங்கள். அப்போது மாற்றம் முழுமையான இழப்பாகத் தோன்றாமல் புதிய தொடக்கத்திற்கான அடித்தளமாக அமையும்."]], "business": [["Demand and dependable delivery", "தேவையும் தொடர்ந்து வழங்கும் திறனும்", "Interest in a business idea and willingness to become a paying customer are different things. The more useful signal is whether people return because the service solves a problem for them. Before interpreting an increase in enquiries as lasting growth, consider whether you can deliver on time and maintain quality. Reputation develops through this repeated experience of reliability.", "ஒரு வியாபார யோசனையைப் பாராட்டுவதும் அதற்காக வாடிக்கையாளராக வருவதும் வேறுபட்டவை. நீங்கள் தரும் சேவை ஒரு தேவையை நிறைவேற்றுவதால் மீண்டும் வருகிறார்களா என்பதே முக்கியம். விசாரணைகள் அதிகரித்தவுடன் நிலையான வளர்ச்சி என்று எடுத்துக்கொள்ளாமல், நேரத்திற்குள் தரமாகச் சேவை வழங்க முடிகிறதா என்பதைப் பாருங்கள். மீண்டும் மீண்டும் கிடைக்கும் நம்பகமான அனுபவத்தில்தான் வியாபாரப் பெயர் உருவாகிறது."], ["Working independently or with a partner", "தனியாகவோ கூட்டாகவோ செயல்படுதல்", "A partner can bring reach, technical ability or continuity that is difficult to create alone. That advantage lasts when the contribution of each person is understood. Discuss who handles customers, who completes the work and who decides when priorities conflict. Friendship can support the arrangement, but everyday clarity is what allows the relationship to carry business pressure.", "தனியாக உருவாக்கச் சிரமமான தொடர்பு, தொழில்நுட்பத் திறன் அல்லது தொடர்ச்சியான செயல்பாட்டை ஒரு கூட்டாளி தரலாம். ஒவ்வொருவரின் பங்களிப்பும் தெளிவாக இருந்தால்தான் அந்த நன்மை நீடிக்கும். வாடிக்கையாளரை யார் கவனிப்பது, வேலையை யார் முடிப்பது, முன்னுரிமை மாறும்போது யார் முடிவெடுப்பது என்பதைப் பேச வேண்டும். நட்பு உதவினாலும் அன்றாடத் தெளிவுதான் வியாபாரச் சுமையைத் தாங்கச் செய்கிறது."]], "finance": [["Income and the feeling of security", "வருமானமும் பாதுகாப்பு உணர்வும்", "Earning more and feeling financially settled do not always happen together. If responsibilities have increased at the same time, the improvement may first appear as the ability to meet existing commitments more comfortably. Look at the stability of the source and the obligations attached to it. That gives a more realistic picture than judging progress only by the largest amount received in one month.", "வருமானம் உயர்வதும் நிதி நிம்மதி கிடைப்பதும் எப்போதும் ஒரே நேரத்தில் நடப்பதில்லை. அதே நேரத்தில் பொறுப்புகளும் அதிகரித்தால் பழைய கடமைகளைச் சிரமமின்றி நிறைவேற்றுவதில்தான் முன்னேற்றம் முதலில் தெரியும். வரவு தரும் வழி தொடர்ந்து உள்ளதா, அதனுடன் என்ன கடமைகள் சேர்கின்றன என்பதையும் பாருங்கள். ஒரு மாதத்தில் வந்த அதிகமான தொகையை மட்டும் வைத்து நிலையான வளர்ச்சி என்று எடுத்துக்கொள்ள முடியாது."], ["Family expectations around resources", "பொருளாதாரத்தைச் சுற்றிய குடும்ப எதிர்பார்ப்புகள்", "Money can carry meanings that go beyond the amount: care, independence, recognition or a sense of duty. A disagreement may therefore concern an expectation that has not been spoken aloud. Distinguish what is necessary, what is a shared preference and what one person feels obliged to provide. This makes the conversation clearer without treating affection as something measured by spending.", "பணம் என்பது தொகையைத் தாண்டி அன்பு, சுயநிலை, மரியாதை அல்லது கடமை என்ற பொருளையும் கொண்டிருக்கலாம். அதனால் கருத்து வேறுபாட்டின் பின்னால் சொல்லப்படாத எதிர்பார்ப்பு இருக்கலாம். அவசியமான தேவை எது, இருவரின் விருப்பம் எது, ஒருவர் மட்டும் கடமையாக உணருவது எது என்று பிரித்துப் பேசுங்கள். செலவின் அளவை வைத்து அன்பை அளவிடாமல் பொருளாதாரப் பேச்சைத் தெளிவாக்க இது உதவும்."]], "marriage": [["Compatibility in ordinary life", "அன்றாட வாழ்க்கையில் வெளிப்படும் இணக்கம்", "A relationship is shaped not only by affection but by the way two people share ordinary decisions. Work schedules, privacy, relatives and household responsibilities can reveal expectations that were not obvious at the beginning. The useful question is not whether both people think alike about everything, but whether a difference can be discussed without making either person feel unheard or controlled.", "அன்பு மட்டுமல்லாமல் அன்றாட முடிவுகளை இருவர் எப்படி பகிர்கிறார்கள் என்பதும் உறவை உருவாக்குகிறது. வேலை நேரம், தனிப்பட்ட இடம், உறவினர்கள், வீட்டுப் பொறுப்புகள் போன்றவற்றில் ஆரம்பத்தில் தெரியாத எதிர்பார்ப்புகள் வெளிப்படும். எல்லா விஷயத்திலும் ஒரே கருத்து இருக்க வேண்டியதில்லை. வேறுபாட்டைப் பேசும்போது ஒருவருடைய குரல் மறுக்கப்படாமலும் கட்டுப்படுத்தப்படுவதாக உணராமலும் இருக்கிறதா என்பதே முக்கியம்."], ["Trust after a disagreement", "கருத்து வேறுபாட்டிற்குப் பிறகு நம்பிக்கையைப் பேணுதல்", "A difficult conversation does not by itself describe the whole relationship. Pay attention to what happens afterwards: whether the concern is understood, whether a promise is followed through and whether both people can return to ordinary warmth. Repeated reassurance without a change in behaviour is different from a small but dependable correction. That distinction is useful when reading the chart's supportive and demanding indications together.", "ஒரு கடினமான உரையாடலே முழு உறவின் தன்மையை முடிவு செய்வதில்லை. அதன் பிறகு கவலை புரிந்துகொள்ளப்பட்டதா, சொன்னதைச் செய்தார்களா, இயல்பான நெருக்கத்திற்குத் திரும்ப முடிந்ததா என்பதையும் பாருங்கள். நடத்தையில் மாற்றமின்றி ஆறுதல் சொல்வதற்கும் சிறிய அளவிலாவது தொடர்ந்து திருத்திக் கொள்வதற்கும் வேறுபாடு உண்டு. ஜாதகத்தில் ஆதரவும் சவாலும் சேர்ந்திருந்தால் இந்த வேறுபாட்டைப் புரிந்துகொள்வது பயன்படும்."]], "children": [["Parenting and the child's individuality", "பெற்றோர் பொறுப்பும் குழந்தையின் தனித்தன்மையும்", "In the parenting part of this reading, encouragement and expectation need to be distinguished. A child may respond well to interest in the process while becoming anxious when every attempt is judged by its result. Notice how you communicate approval, disappointment and comparison. The quality of that interaction is a practical expression of this life area, separate from any question about whether or when a child will be born.", "பெற்றோர் அணுகுமுறையில் ஊக்கத்தையும் எதிர்பார்ப்பையும் பிரித்துப் பார்க்க வேண்டும். குழந்தை செய்யும் முயற்சியில் ஆர்வம் காட்டுவது உதவலாம்; ஒவ்வொரு முயற்சியையும் முடிவால் மட்டும் மதிப்பிட்டால் பதற்றம் உருவாகலாம். பாராட்டு, ஏமாற்றம், மற்றவருடன் ஒப்பிடுதல் ஆகியவற்றை எப்படித் தெரிவிக்கிறீர்கள் என்பதைக் கவனியுங்கள். இந்த உறவின் தரம் இப்பகுதியின் நடைமுறை வெளிப்பாடு; குழந்தை எப்போது பிறக்கும் என்ற கேள்வியிலிருந்து இது வேறுபட்டது."], ["Creativity and the work you nurture", "படைப்பாற்றலும் வளர்த்தெடுக்கும் முயற்சியும்", "The same life area also concerns the patience to develop an idea, a student or a creative piece of work. Initial enthusiasm is only one stage. Revising an imperfect attempt and allowing it time to mature often matter more than starting repeatedly. If parenting is not relevant to your present life, this part can still be understood through what you teach, create and help to grow.", "இதே வாழ்க்கைப் பகுதி ஒரு கருத்தை, மாணவரை அல்லது படைப்பை வளர்த்தெடுக்கும் பொறுமையையும் குறிக்கிறது. ஆரம்ப ஆர்வம் ஒரு கட்டம் மட்டுமே. குறை உள்ள முயற்சியைத் திருத்தி முதிரச் செய்வது, அடிக்கடி புதிதாக ஆரம்பிப்பதைவிட முக்கியமாகலாம். உங்கள் தற்போதைய வாழ்க்கையில் பெற்றோர் பொறுப்பு பொருந்தாவிட்டாலும் கற்பிப்பது, உருவாக்குவது, மற்றவரின் வளர்ச்சிக்கு உதவுவது ஆகியவற்றின் வழியாக இந்த விளக்கத்தைப் புரிந்துகொள்ளலாம்."]], "education": [["Understanding and examination performance", "புரிதலும் தேர்வில் வெளிப்படுத்தும் திறனும்", "Understanding a subject and showing that understanding under a time limit are different abilities. If the result is weaker than the effort, look at where the gap appears: recall, reading the question, organising the answer or completing it in time. This is more informative than labelling yourself capable or incapable from one examination. The chart reading should be connected with that actual learning pattern.", "பாடம் புரிவதும் குறிப்பிட்ட நேரத்திற்குள் அதைத் தேர்வில் வெளிப்படுத்துவதும் வெவ்வேறு திறன்கள். உழைப்பிற்கேற்ற மதிப்பெண் வரவில்லை என்றால் நினைவுகூர்தல், கேள்வியைப் புரிதல், விடையை ஒழுங்குபடுத்துதல், நேரத்திற்குள் முடித்தல் ஆகியவற்றில் எங்கு இடைவெளி உள்ளது என்று பாருங்கள். ஒரு தேர்வை வைத்து திறமை உண்டு அல்லது இல்லை என்று முடிவு செய்வதைவிட இது பயனுள்ளது. ஜாதக விளக்கத்தையும் உண்மையான கற்றல் முறையுடன் இணைத்துப் புரிந்துகொள்ள வேண்டும்."], ["Choosing a course with continuity", "தொடர்ந்து கற்கக்கூடிய துறையைத் தேர்ந்தெடுத்தல்", "Interest is useful when it survives contact with the ordinary work of a subject. Before committing to a new course, understand its daily practice, not only its attractive outcome. Consider whether you enjoy the type of problem it asks you to solve and whether the required time fits your circumstances. A direction that you can sustain may become more valuable than one chosen mainly for its reputation.", "ஒரு பாடத்தின் அன்றாடப் பயிற்சியிலும் ஆர்வம் தொடர்ந்தால்தான் அது நீண்டகாலக் கற்றலுக்கு உதவும். புதிய படிப்பைத் தேர்ந்தெடுக்கும் முன் அதன் முடிவில் கிடைக்கும் பெயரை மட்டும் பார்க்காமல் தினமும் என்ன செய்ய வேண்டியிருக்கும் என்பதை அறியுங்கள். அந்தத் துறை கேட்கும் கேள்விகளைத் தீர்ப்பதில் விருப்பம் உள்ளதா, தேவையான நேரம் உங்கள் சூழலுக்குப் பொருந்துகிறதா என்பதையும் பாருங்கள். பெயருக்காகத் தேர்ந்தெடுப்பதைவிட தொடர்ந்து கற்கக்கூடிய பாதை பயன் தரலாம்."]], "property": [["A home that supports your life", "உங்கள் வாழ்க்கைக்கு ஏற்ற வீடு", "The wish for a home often includes the wish for stability, privacy or relief from an unsettled routine. Identify which of those needs matters most now. A place that looks like an improvement may create a heavier journey or reduce access to familiar help. The meaningful comparison is between the daily life each option makes possible, not only the appearance or symbolic status of ownership.", "வீடு வேண்டும் என்ற விருப்பத்திற்குள் நிலைத்தன்மை, தனியுரிமை அல்லது அலைச்சல் குறைய வேண்டும் என்ற தேவை இருக்கலாம். இப்போது அதில் எது முக்கியம் என்பதை அறியுங்கள். வெளியில் நல்ல முன்னேற்றமாகத் தோன்றும் இடம் அன்றாடப் பயணத்தை அதிகரிக்கலாம் அல்லது பழகிய உதவியைத் தூரப்படுத்தலாம். வீடு என்ற அடையாளத்தை மட்டும் பார்க்காமல் ஒவ்வொரு இடமும் எந்த வகையான தினசரி வாழ்க்கையைத் தருகிறது என்பதை ஒப்பிடுவது பொருத்தமானது."], ["Comfort and continuing responsibility", "வசதியுடன் சேரும் தொடர்ச்சியான பொறுப்பு", "A property or vehicle can improve convenience while adding upkeep and coordination. Think about who will handle those responsibilities and whether the improvement serves a recurring need. The desire to settle deserves respect, but it becomes clearer when separated from pressure to match another person's timetable. The chart's timing indications describe a period of emphasis, not a requirement to complete a purchase by a fixed date.", "சொத்து அல்லது வாகனம் வசதியை அதிகரிக்கும் அதே நேரத்தில் பராமரிப்பையும் ஒருங்கிணைப்பையும் சேர்க்கும். அந்தப் பொறுப்பை யார் ஏற்கிறார்கள், தொடர்ந்து உள்ள தேவையை அது நிறைவேற்றுகிறதா என்று பாருங்கள். நிலையாக அமர வேண்டும் என்ற விருப்பத்தை மற்றவர் முடித்துவிட்டார் என்பதால் வரும் அவசரத்திலிருந்து பிரித்துப் புரிந்துகொள்ளுங்கள். ஜாதகத்தில் வரும் காலச் சுட்டி அந்த விஷயம் முக்கியமாகும் கட்டத்தைக் குறிக்கும்; அந்தத் தேதிக்குள் வாங்கியே ஆக வேண்டும் என்ற கட்டாயம் அல்ல."]], "debt": [["Obligations that need a clear order", "வரிசைப்படுத்த வேண்டிய கடமைகள்", "Several unfinished obligations can feel like one large problem even when they have different causes. Separate a recurring responsibility from a disputed demand or a task that is simply delayed. Knowing which kind of issue you are dealing with makes the next conversation more precise. In this reading, pressure calls for attention to the structure of the problem rather than assuming that every obligation will end badly.", "முடிக்காத பல கடமைகள் ஒவ்வொன்றுக்கும் வேறு காரணம் இருந்தாலும் ஒரே பெரிய சுமையாகத் தோன்றலாம். தொடர்ந்து செய்ய வேண்டிய பொறுப்பு, கருத்து வேறுபாடு உள்ள கோரிக்கை, தாமதமாகிய வேலை ஆகியவற்றைப் பிரித்துப் பாருங்கள். எந்த வகையான பிரச்சினை என்பதை அறிந்தால் அடுத்து யாருடன் எதைப் பேச வேண்டும் என்பது தெளிவாகும். இங்கு அழுத்தம் என்று வருவது பிரச்சினையின் அமைப்பைக் கவனிக்க வேண்டும் என்பதே; எல்லாக் கடமைகளும் மோசமாக முடியும் என்று பொருள் அல்ல."], ["Handling opposition without losing direction", "எதிர்ப்பால் உங்கள் நோக்கம் மாறாமல் செயல்படுதல்", "Competition can sharpen effort, but it can also draw you into proving something that no longer serves your purpose. Keep the desired outcome separate from the wish to answer an opponent. Clear records, agreed responsibilities and a measured response make it easier to see what remains unresolved. A chart cannot establish the outcome of a dispute or replace the relevant professional assessment.", "போட்டி முயற்சியைத் தூண்டலாம்; ஆனால் உங்கள் நோக்கத்திற்குப் பயன்படாத விஷயத்தில் உங்களை நிரூபிக்க வேண்டும் என்ற சுமையையும் தரலாம். எதிராளிக்குப் பதில் சொல்ல வேண்டும் என்ற எண்ணத்திலிருந்து உங்களுக்கு வேண்டிய முடிவைப் பிரித்துப் பாருங்கள். தெளிவான பதிவு, ஒப்புக்கொண்ட பொறுப்பு, அளவான பதில் ஆகியவை இன்னும் தீராத விஷயம் எது என்பதை அறிய உதவும். ஒரு தகராறின் முடிவை ஜாதகம் உறுதி செய்யாது; அதற்குரிய நிபுணரின் மதிப்பீட்டை இது மாற்றாது."]], "health": [["Daily functioning and the load you carry", "அன்றாடச் செயல்பாடும் நீங்கள் ஏற்கும் சுமையும்", "This part of the horoscope is best read as a reflection on care, rest and the demands placed on your routine. A busy or demanding period may make those needs more noticeable without identifying a disease. Notice what actually changes in everyday functioning rather than looking for an illness to match an astrological phrase. Persistent symptoms need appropriate medical assessment, regardless of whether the chart is described as supportive.", "ஜாதகத்தின் இந்தப் பகுதியைப் பராமரிப்பு, ஓய்வு, அன்றாடச் சுமை பற்றிய விளக்கமாக வாசிப்பது பொருத்தமானது. அதிக வேலை உள்ள காலத்தில் அந்தத் தேவைகள் தெளிவாகத் தெரியலாம்; அதனால் ஒரு நோய் இருப்பதாகக் கொள்ள முடியாது. ஜோதிடச் சொல்லுக்கு ஏற்ற நோயைத் தேடாமல் அன்றாடச் செயல்பாட்டில் உண்மையில் என்ன மாறுகிறது என்பதைக் கவனியுங்கள். தொடரும் அறிகுறிகளுக்கு உரிய மருத்துவ மதிப்பீடு தேவை; ஜாதகத்தில் ஆதரவு இருப்பதாகக் கூறப்படுவதால் அதை ஒத்திவைக்கக் கூடாது."], ["Accepting help and allowing recovery", "உதவியை ஏற்றுக்கொள்வதும் மீள நேரம் கொடுப்பதும்", "Being dependable does not mean carrying every task without rest. If responsibilities leave little room for ordinary care, consider which duties can be shared and which expectations need to be discussed. The practical meaning of a supportive arrangement may be the availability of help, not an absence of all difficulty. A demanding indication is likewise a prompt for attention, not a diagnosis or a prediction of an accident.", "நம்பகமாக இருப்பது என்றால் ஓய்வின்றி எல்லா வேலையையும் தனியாகச் செய்வது அல்ல. வழக்கமான பராமரிப்பிற்கே நேரமில்லாத அளவு பொறுப்பு இருந்தால் எந்தப் பணியைப் பகிரலாம், எந்த எதிர்பார்ப்பைப் பேசித் தெளிவுபடுத்தலாம் என்று பாருங்கள். ஆதரவு உள்ள அமைப்பு என்பது சிரமமே வராது என்பதைக் காட்டாமல் உதவி கிடைக்கும் வழியையும் குறிக்கலாம். கவனம் தேவை என்ற சுட்டியும் நோய் கண்டறிதலோ விபத்து உறுதியோ அல்ல."]], "family": [["Affection and the division of responsibility", "பாசமும் பொறுப்பைப் பகிரும் முறையும்", "Family members can care for one another while carrying different ideas about what care should look like. One may express it through practical help, another through frequent contact and another through financial contribution. Differences become easier to discuss when these expectations are named. Otherwise, a contribution may go unnoticed simply because it arrives in a form that another person did not expect.", "குடும்பத்தில் பாசம் இருந்தாலும் அதை வெளிப்படுத்தும் முறை ஒவ்வொருவருக்கும் வேறாக இருக்கலாம். ஒருவர் நேரடி உதவியால், மற்றவர் அடிக்கடி தொடர்புகொள்வதால், இன்னொருவர் பொருளாதாரப் பங்களிப்பால் அக்கறை காட்டலாம். அந்த எதிர்பார்ப்புகளைச் சொல்லிப் புரிந்துகொண்டால் வேறுபாட்டைப் பேசுவது சுலபமாகும். இல்லையெனில் ஒருவர் செய்யும் உதவி மற்றவர் எதிர்பார்த்த வடிவில் இல்லாததால் கவனிக்கப்படாமல் போகலாம்."], ["Your place within changing family needs", "மாறும் குடும்பத் தேவைகளில் உங்கள் பங்கு", "The role you carried earlier may no longer fit everyone's present circumstances. A person who once relied on you may need more independence, while someone previously independent may need help. Revisit arrangements instead of assuming that the old division of responsibility must continue forever. That adjustment can preserve closeness while making room for the different stage each person has reached.", "முன்பு நீங்கள் ஏற்ற பங்கு இன்றைய குடும்பச் சூழலுக்கு அப்படியே பொருந்தாமல் இருக்கலாம். உங்களைச் சார்ந்திருந்தவருக்குச் சுயநிலை தேவைப்படலாம்; தனியாகச் செயல்பட்டவருக்கு இப்போது உதவி தேவைப்படலாம். பழைய பொறுப்புப் பகிர்வே எப்போதும் தொடர வேண்டும் என்று கொள்ளாமல் மறுபரிசீலனை செய்யுங்கள். ஒவ்வொருவரின் வாழ்க்கைக் கட்டத்திற்கும் இடம் கொடுக்கும்போது நெருக்கத்தைப் பேணியபடியே பொறுப்பை மாற்றி அமைக்க முடியும்."]], "parents": [["Guidance and making your own decisions", "வழிகாட்டலும் உங்கள் சொந்த முடிவும்", "Respecting a parent's experience does not require every decision to follow the same path. Their concern may be directed toward security while yours is directed toward a different kind of opportunity. Explain the practical reasoning behind your choice, including what you have considered and what remains uncertain. This creates a more useful conversation than treating disagreement as proof that either side does not care.", "பெற்றோரின் அனுபவத்தை மதிப்பது என்றால் எல்லா முடிவும் அதே பாதையில் இருக்க வேண்டும் என்பதல்ல. அவர்கள் பாதுகாப்பை முன்னிலைப்படுத்தலாம்; நீங்கள் வேறுவகையான வாய்ப்பைப் பார்க்கலாம். என்னென்ன பரிசீலித்தீர்கள், எதில் இன்னும் தெளிவு தேவை என்பதுடன் உங்கள் முடிவின் நடைமுறைக் காரணத்தை விளக்குங்கள். கருத்து வேறுபாட்டை அக்கறையின்மையாகக் கருதுவதைவிட இந்த உரையாடல் பயனுள்ளதாக அமையும்."], ["Care that can be sustained", "தொடர்ந்து செய்யக்கூடிய பராமரிப்பு", "When an elder needs support, emotional concern and the organisation of care become separate responsibilities. Clarify who can be present, who can coordinate and what help is realistically available. A sustainable arrangement is often more useful than a large promise made in a moment of worry. This reading concerns your experience of responsibility and support; it does not determine a parent's health or lifespan.", "மூத்தவருக்கு உதவி தேவைப்படும்போது மனதளவிலான அக்கறையும் பராமரிப்பை ஏற்பாடு செய்வதும் தனித்தனி பொறுப்புகள். யார் உடனிருக்க முடியும், யார் ஒருங்கிணைக்க முடியும், உண்மையில் என்ன உதவி கிடைக்கிறது என்பதைத் தெளிவுபடுத்துங்கள். கவலையில் பெரிய வாக்குறுதி தருவதைவிட தொடர்ந்து செய்யக்கூடிய ஏற்பாடு பயனுள்ளதாக இருக்கும். இவ்வாசிப்பு உங்கள் பொறுப்பு மற்றும் ஆதரவு அனுபவத்தைப் பற்றியது; பெற்றோரின் உடல்நிலையையோ ஆயுளையோ முடிவு செய்வதல்ல."]], "siblings": [["Support without comparison", "ஒப்பீடு இல்லாத ஒத்துழைப்பு", "Siblings can reach different stages at different times without one person's progress diminishing another's. Comparison becomes especially unhelpful when the circumstances and responsibilities are unlike. Focus on the kind of support each person can actually offer. A practical exchange of information, time or encouragement can strengthen the relationship more than an expectation that everyone should contribute in exactly the same way.", "சகோதரர்கள் வெவ்வேறு நேரங்களில் வெவ்வேறு நிலையை அடையலாம்; ஒருவரின் வளர்ச்சி மற்றவரின் மதிப்பைக் குறைப்பதில்லை. சூழலும் பொறுப்பும் வேறாக இருக்கும்போது ஒப்பீடு மேலும் பொருந்தாது. ஒவ்வொருவரும் உண்மையில் எந்த வகையான உதவியைத் தர முடியும் என்பதைப் பாருங்கள். தகவல், நேரம், ஊக்கம் போன்ற நடைமுறைப் பங்களிப்பு உறவை வலுப்படுத்தலாம்; எல்லாரும் ஒரே மாதிரியாக உதவ வேண்டும் என்ற எதிர்பார்ப்பு அவசியமில்லை."], ["Shared tasks and personal boundaries", "கூட்டு வேலையும் தனிப்பட்ட எல்லையும்", "When relatives work together, the familiarity of the relationship can make an unspoken agreement seem sufficient. Later, a difference about time or responsibility may be taken personally. State the arrangement plainly while goodwill is strong. Clear limits need not reduce affection; they can prevent a practical misunderstanding from becoming a judgment about the entire relationship.", "உறவினர்கள் சேர்ந்து வேலை செய்யும்போது பழக்கம் இருப்பதால் சொல்லாமலேயே புரிந்துகொள்வார்கள் என்று நினைக்கலாம். பின்னர் நேரம் அல்லது பொறுப்பில் வேறுபாடு வந்தால் அதைத் தனிப்பட்ட குறையாக எடுத்துக்கொள்ளலாம். நல்ல புரிதல் இருக்கும்போதே ஏற்பாட்டைத் தெளிவாகப் பேசுவது உதவும். எல்லை வகுப்பதால் பாசம் குறைய வேண்டியதில்லை; நடைமுறைப் புரிதல் குறை முழு உறவின் மீதான குற்றச்சாட்டாக மாறாமல் தடுக்கலாம்."]], "travel": [["A journey and a lasting relocation", "பயணமும் நீண்டகால இடமாற்றமும்", "A wish to travel, a temporary assignment and a lasting move involve different levels of commitment. First identify which one fits the opportunity in front of you. A distant place can seem attractive because it represents a fresh start, but the daily reality includes work, language, housing and access to help. These details determine how useful the opening becomes in your actual life.", "பயணம் செய்யும் விருப்பம், தற்காலிகப் பணி, நீண்டகால இடமாற்றம் ஆகியவற்றின் பொறுப்பு வேறுபடும். முன் உள்ள வாய்ப்பு எந்த வகையைச் சேர்ந்தது என்பதை முதலில் அறியுங்கள். தொலைதூர இடம் புதிய தொடக்கமாகத் தோன்றலாம்; ஆனால் அங்கு வேலை, மொழி, வசிப்பிடம், உதவி கிடைக்கும் வழி ஆகியவை அன்றாட வாழ்க்கையை நிர்ணயிக்கும். இந்த விவரங்கள்தான் வாய்ப்பு உண்மையில் எவ்வளவு பயன்படும் என்பதைத் தெளிவாக்கும்."], ["Keeping continuity after a move", "இடம் மாறிய பிறகும் வாழ்க்கையின் தொடர்ச்சியைப் பேணுதல்", "Moving can change familiar routines before it produces the hoped-for improvement. Consider how you will stay connected with important people and how ordinary responsibilities will be handled during the transition. Feeling unfamiliar at first is different from an arrangement being unsuitable. Review the actual conditions as they develop, rather than requiring a new place to solve every difficulty immediately.", "எதிர்பார்த்த முன்னேற்றம் வருவதற்கு முன்பே இடமாற்றம் பழகிய ஒழுங்கை மாற்றிவிடலாம். முக்கியமானவர்களுடன் தொடர்பை எப்படிப் பேணுவது, இடைக்காலத்தில் வழக்கமான பொறுப்புகளை யார் கவனிப்பது என்பதையும் யோசியுங்கள். ஆரம்பத்தில் பழகாமல் இருப்பதற்கும் அந்த அமைப்பே பொருந்தாததற்கும் வேறுபாடு உண்டு. புதிய இடம் எல்லாச் சிரமத்தையும் உடனே தீர்க்க வேண்டும் என்று எதிர்பார்க்காமல் உருவாகும் உண்மை நிலையை வைத்து மதிப்பிடுங்கள்."]], "status": [["Being seen and being relied upon", "கவனிக்கப்படுவதும் நம்பப்படுவதும்", "Visibility can increase before influence becomes stable. An invitation to speak, lead or represent a group may bring attention, but continuing respect depends on how you handle the responsibility. Notice whether you are being given real room to contribute or only an outward position. A role becomes more satisfying when the recognition and the work behind it remain connected.", "நிலையான செல்வாக்கு உருவாகும் முன்பே வெளிப்புறக் கவனம் அதிகரிக்கலாம். பேசுவதற்கோ வழிநடத்துவதற்கோ ஒரு குழுவைப் பிரதிநிதித்துவப்படுத்துவதற்கோ வாய்ப்பு கிடைக்கலாம்; தொடரும் மரியாதை அந்தப் பொறுப்பை எப்படிச் செய்கிறீர்கள் என்பதில் அமையும். உண்மையாகப் பங்களிக்க இடம் தரப்படுகிறதா அல்லது பெயரளவிலான நிலை மட்டுமா என்பதைப் பாருங்கள். அங்கீகாரமும் அதன் பின்னுள்ள வேலையும் இணைந்தால் அந்த நிலை மனநிறைவைத் தரும்."], ["A reputation you can maintain", "தொடர்ந்து காப்பாற்றக்கூடிய நற்பெயர்", "Trying to satisfy every expectation can make a visible role exhausting. Decide what you can consistently stand behind and communicate those limits clearly. Reliability often grows through a few commitments fulfilled well, rather than through saying yes to every request. That allows recognition to develop around work that reflects your actual capacity and values.", "எல்லோரின் எதிர்பார்ப்பையும் நிறைவேற்ற முயன்றால் வெளிப்படையான பொறுப்பு சோர்வைத் தரலாம். தொடர்ந்து நம்பிக்கையுடன் செய்யக்கூடியது எது என்பதை முடிவு செய்து அதன் எல்லையைத் தெளிவாகக் கூறுங்கள். எல்லா வேண்டுகோளையும் ஏற்றுக்கொள்வதைவிட சில பொறுப்புகளைச் சரியாக நிறைவேற்றுவதால் நம்பகத்தன்மை வளரும். அப்போது உங்கள் உண்மையான திறனுக்கும் மதிப்புகளுக்கும் ஏற்ற வேலையின் வழியாக நற்பெயர் உருவாகும்."]], "fortune": [["Recognising useful help", "பயன்படும் உதவியை அறிந்துகொள்ளுதல்", "What feels like good fortune may arrive through a person who shares information at the right time, a teacher who sees an ability or an opening created by earlier effort. Receiving help is only the beginning. The opportunity becomes useful when you understand what it asks of you and respond with preparation. This gives a practical meaning to supportive indications without assuming that events will arrange themselves.", "அதிர்ஷ்டம் என்று உணரப்படுவது சரியான நேரத்தில் தகவல் தருபவர், திறனை அடையாளம் காணும் ஆசிரியர் அல்லது முன்பு செய்த முயற்சியால் திறக்கும் வாய்ப்பாக வரலாம். உதவி கிடைப்பது ஆரம்பம் மட்டுமே. அந்த வாய்ப்பு உங்களிடம் என்ன எதிர்பார்க்கிறது என்பதை அறிந்து தயாராகச் செயல்பட்டால்தான் பயனாகும். எல்லாம் தானாக அமையும் என்று எதிர்பார்க்காமல் ஆதரவான சுட்டிக்கு நடைமுறைப் பொருள் கொடுப்பது இதுவே."], ["Learning from a guide without dependence", "வழிகாட்டலை ஏற்றும் சார்பைத் தவிர்த்தும் கற்றல்", "A good guide expands your ability to judge, rather than requiring permanent dependence. Listen to the reasoning behind advice and compare it with the circumstances you actually face. An introduction, recommendation or lesson can change your direction, but you still need to decide how it fits your responsibilities. Gratitude and independent judgment can exist together.", "நல்ல வழிகாட்டல் எப்போதும் ஒருவரைச் சார்ந்திருக்கச் செய்வதைவிட உங்கள் முடிவெடுக்கும் திறனை வளர்க்கும். அறிவுரையின் பின்னுள்ள காரணத்தைக் கேட்டு உங்கள் உண்மைச் சூழலுடன் ஒப்பிடுங்கள். ஒரு அறிமுகம், பரிந்துரை அல்லது பாடம் பாதையை மாற்றலாம்; அது உங்கள் பொறுப்பிற்கு எப்படிப் பொருந்துகிறது என்பதைக் கண்டறிவது உங்கள் பங்காகும். நன்றியுணர்வுடன் இருப்பதும் சொந்தமாகச் சிந்திப்பதும் ஒன்றாக இருக்க முடியும்."]], "spiritual": [["Belief in everyday conduct", "அன்றாட நடத்தையில் வெளிப்படும் நம்பிக்கை", "Spiritual interest can become meaningful through the way you respond to frustration, responsibility and another person's needs. A practice that is personally significant may offer a rhythm for reflection, but its place in your life is clearer when it supports patience and thoughtful action. Notice whether the practice helps you return to ordinary duties with greater clarity rather than postponing an issue that still needs attention.", "ஆன்மிக ஆர்வம் ஏமாற்றம், பொறுப்பு, மற்றவரின் தேவை ஆகியவற்றை நீங்கள் அணுகும் விதத்திலும் பொருள் பெறுகிறது. உங்களுக்கு முக்கியமான வழிபாடு சிந்தனைக்கான ஒழுங்கைத் தரலாம்; பொறுமையையும் தெளிவான செயலையும் வளர்க்கும்போது அதன் இடம் மேலும் தெளிவாகும். கவனிக்க வேண்டிய விஷயத்தை ஒத்திவைக்காமல் அன்றாடக் கடமைக்குத் தெளிவுடன் திரும்ப உதவுகிறதா என்பதைப் பாருங்கள்."], ["Quietness and remaining connected", "அமைதியும் உறவுடன் இணைந்திருப்பதும்", "A need for solitude can be different from a wish to withdraw from everyone. Quiet time may help you understand an experience before speaking about it, while continued contact prevents reflection from becoming isolation. The useful balance depends on your present responsibilities and preferences. There is no need to imitate another person's form of devotion for your own reflection to have value.", "தனியாக அமைதியில் இருக்க வேண்டும் என்பதும் எல்லோரிடமிருந்தும் விலக வேண்டும் என்பதும் வேறுபட்டவை. ஒரு அனுபவத்தைப் பற்றிப் பேசுவதற்கு முன் புரிந்துகொள்ள அமைதியான நேரம் உதவலாம்; தொடர்பைப் பேணுவது சிந்தனை தனிமைப்படுதலாக மாறாமல் காக்கும். உங்கள் தற்போதைய பொறுப்புக்கும் விருப்பத்திற்கும் ஏற்ற சமநிலையே பயன்படும். மற்றவரின் வழிபாட்டு முறையை அப்படியே பின்பற்றினால்தான் உங்கள் சிந்தனைக்கு மதிப்பு உண்டு என்பதில்லை."]]};
function v254Sections(sections){return {sections:sections.filter(s=>s.paragraphs.filter(Boolean).length).map(s=>({...s,paragraphs:s.paragraphs.filter(Boolean)})),paragraphs:sections.flatMap(s=>s.paragraphs).filter(Boolean)}}
function v255RulerReading(h,lang){
 const ta=lang==='ta',c=h.rulerCondition;if(!c)return '';
 const name=v251Planet(h.lord,lang),n=h.house,good=c.exalted||c.ownSign||c.moolatrikona,low=c.debilitated,ratio=c.ratio;
 const dignity=ta?(c.exalted?'உச்ச நிலையில்':c.moolatrikona?'மூலத்திரிகோண நிலையில்':c.ownSign?'சொந்த ராசியில்':low?'நீச நிலையில்':'உச்சம், ஆட்சி, நீசம் ஆகிய சிறப்பு நிலைகள் இல்லாமல்'):(c.exalted?'exalted':c.moolatrikona?'in Moolatrikona':c.ownSign?'in its own sign':low?'debilitated':'without exaltation, own-sign or debilitation status');
 const intro=ta?`${n}-ஆம் பாவத்தை நடத்தும் ${name} ${dignity} உள்ளது.`:`${name}, which rules house ${n}, is ${dignity}.`;
 const meaning=ta?(good?' இந்தப் பாவம் குறிக்கும் விஷயத்தைச் செயலாக்கும் அதிபதிக்கே ஆதாரம் இருப்பதால், வெளியில் வாய்ப்பு உருவாகும்போது அதை பயன்படுத்திக்கொள்ளும் பக்கம் வலுப்படுகிறது. எனினும் அதிபதி அமர்ந்த பாவமும் மற்ற கிரகத் தொடர்புகளும் அந்த வாய்ப்பு எந்த வழியில் வரும் என்பதை மாற்றுகின்றன.':low?' இங்கு விருப்பத்தை விட அதைத் தொடர்ந்து நிறைவேற்றும் வசதி முக்கியமாகிறது. ஆரம்பிப்பதற்கான ஆர்வம் இருந்தாலும் சூழலின் உதவி, தெளிவான ஏற்பாடு, மீண்டும் முயலும் பொறுமை ஆகியவை தேவைப்படலாம். இந்த ஒரு நிலையால் மட்டும் முழுப் பலனைத் தீர்மானிக்காமல் கீழுள்ள ஆதரவுகளையும் சேர்த்தே முடிவு கூற வேண்டும்.':' இந்தப் பாவத்தின் பலனை ஒரு ராசி பலச் சொல்லால் மட்டும் முடிவு செய்ய முடியாது. அதிபதி எங்கு அமர்ந்துள்ளது, எந்தக் கிரகங்கள் இந்தப் பாவத்தைத் தொடர்புகொள்கின்றன, துணை ஜாதகம் என்ன கூறுகிறது என்பவை இங்கு கூடுதல் முக்கியத்துவம் பெறுகின்றன.'):(good?' The ruler itself has a supporting dignity, adding a reason that an opportunity in this area can be put to use. Its occupied house and the other influences still describe the route and the conditions through which that opportunity can develop.':low?' Here the ability to sustain an intention deserves as much attention as the intention itself. External support, clear arrangements and patient follow-through may matter. This one condition is considered together with the supporting factors below, rather than being treated as the entire outcome.':' A dignity label alone does not settle this area. The ruler’s placement, the planets influencing the house and the available divisional evidence carry more of the interpretation.');
 const strength=ratio==null?'':ta?(ratio>=1?` கிடைக்கும் கிரக பலக் கணக்கில் ${name} தேவையான அளவை எட்டுகிறது. இது செயல்படும் திறனுக்கான ஆதாரம்; நடக்கும் எல்லா நிகழ்வுகளும் சுலபமாக இருக்கும் என்ற உறுதி அல்ல.`:` கிடைக்கும் கிரக பலக் கணக்கில் ${name} தேவையான அளவிற்குக் கீழே உள்ளது. ஆகவே வாய்ப்பு பற்றிய வாசிப்புடன் அதை நடைமுறையில் தொடர்ந்து நடத்தும் ஆற்றலையும் தனியாகக் கவனிக்கிறோம்.`):(ratio>=1?` The available strength calculation also reaches the required threshold for ${name}. That concerns capacity to act, rather than a promise that every event will be easy.`:` The available strength calculation is below the required threshold for ${name}. An opening therefore needs to be considered separately from the ability to sustain it in practice.`);
 return intro+meaning+strength;
}
function v255HouseConnections(h,e,lang){
 const ta=lang==='ta',n=Number(h.house),dest=arr(e.houses).find(q=>Number(q.house)===Number(h.lordHouse));if(!dest)return [];
 const theme=V253_ROUTE[Number(dest.house)],target=theme?.[ta?1:0];if(!target)return [];
 const ruler=v251Planet(h.lord,lang),first=ta?`${n}-ஆம் பாவத்தின் அதிபதி ${ruler} ${dest.house}-ஆம் பாவத்தில் இருப்பதால் ${target} இந்தப் பலன் வெளிப்படும் சூழலாகிறது.`:`With ${ruler}, ruler of house ${n}, in house ${dest.house}, ${target} forms part of the setting in which this life area develops.`;
 let reading;
 if(n===Number(dest.house))reading=ta?' அதிபதி தன் பாவத்திலேயே இருப்பதால் இந்த வாழ்க்கைப் பகுதியின் தேவையும் அதைச் செயல்படுத்தும் வழியும் நேரடியாக இணைகின்றன. வேறு துறையில் மாற்றம் வருவதற்காக மட்டும் காத்திருப்பதைவிட இங்கேயே நீங்கள் அமைக்கும் ஒழுங்கும் முடிவும் முக்கியமாகின்றன. பிற கிரகங்கள் தரும் அழுத்தம் இருந்தால் அந்த நேரடித்தன்மை அதிகப் பொறுப்பாகவும் உணரப்படலாம்.':' The ruler remains in its own house, connecting the needs of this area directly with how they are handled. Decisions and arrangements made here can matter more than waiting for a change elsewhere. Any pressure from other planets may make that direct involvement feel like increased responsibility.';
 else if(h.state==='support'&&dest.state==='pressure')reading=ta?' முதலில் பார்த்த பாவத்தில் ஆதரவு இருந்தாலும், அந்தப் பலன் வெளிப்படும் இடத்தில் கூடுதல் சிரமம் தெரிகிறது. அதனால் திறன் அல்லது வாய்ப்பு இருப்பதற்கும் அதை வசதியாக அனுபவிப்பதற்கும் இடையில் இடைவெளி இருக்கலாம். மேலே கூறிய நல்ல பலனை மறுப்பதல்ல; அதற்கான சூழலை உருவாக்கும் வேலை இன்னும் தேவைப்படும் என்பதே இந்த இணைப்பின் பொருள்.':' The starting house is supportive, but the destination carries more pressure. Ability or opportunity can therefore exist before the circumstances become comfortable enough to use it. This qualifies the supportive reading: the setting through which the result develops still needs work.';
 else if(h.state==='pressure'&&dest.state==='support')reading=ta?' முதலில் சிரமம் காட்டும் பாவத்திற்கு, அதிபதி அமர்ந்த இடத்தில் ஆதரவு கிடைக்கிறது. அதனால் பிரச்சினையை அதே முறையில் மீண்டும் அணுகுவதைவிட இங்கு குறிக்கப்படும் மனிதர்கள், அனுபவம் அல்லது வாய்ப்பின் வழியாக உதவி கிடைக்கலாம். சிரமமே இல்லை என்று மாற்றிக் கூறாமல், அதைத் தாங்கிக்கொள்ளும் மற்றொரு வழி ஜாதகத்தில் உள்ளது என்று வாசிக்கிறோம்.':' A demanding starting house connects to a better-supported destination. Help may become available through the people, experience or opportunities represented there. This does not erase the original difficulty; it identifies a different route through which it may become more manageable.';
 else if(dest.state==='support')reading=ta?' அதிபதி அமர்ந்த இடமும் ஆதரவாக இருப்பதால் இங்கு கூறிய தொடர்பைப் பயன்படுத்திக்கொள்ளும் வாய்ப்பு உள்ளது. தேவையைத் தெளிவாகச் சொல்லி, கிடைக்கும் உதவியைப் பணியாக மாற்றும்போது பலன் அதிகம் தெரியும். தொடர்பு இருப்பது மட்டும் போதாது; அந்தத் தொடர்பின் வழியாக நீங்கள் ஏற்கும் பொறுப்பும் தொடர்ந்து செயல்பட வேண்டும்.':' The destination also has support, giving a reason to make use of this connection. Its value becomes clearer when a need is expressed and available help is translated into a workable responsibility. The existence of a connection alone is not the same as making sustained use of it.';
 else if(dest.state==='pressure')reading=ta?' அதிபதி அமர்ந்த இடத்தில் பொறுமை தேவைப்படும் நிலை இருப்பதால் இந்தப் பலன் நேராகவும் உடனடியாகவும் வெளிப்படும் என்று சொல்ல முடியாது. அந்த இடத்தின் கடமையைச் சரிசெய்த பிறகே இங்கு முன்னேற்றம் தெளிவாகலாம். தடை என்ற ஒரே சொல்லில் நிறுத்தாமல், எந்தச் சூழல் முன்னேற்றத்தை மெதுவாக்குகிறது என்பதைக் காட்டும் தொடர்பாக இதைப் பார்க்கிறோம்.':' The destination needs more care, so the result may not develop in a direct or immediate way. A responsibility in that connected area may have to be addressed first. The connection helps explain the setting that slows progress rather than reducing the whole reading to a statement of obstruction.';
 else reading=ta?' அதிபதி அமர்ந்த இடம் கலப்பு நிலையில் இருப்பதால் ஒரே வழியில் எப்போதும் ஒரே மாதிரியான அனுபவம் இருக்காது. சில நேரங்களில் உதவியாக இருக்கும் அதே தொடர்பு வேறு நேரத்தில் பொறுப்பையும் சேர்க்கலாம். பயன் தரும் பங்களிப்பு எது, சுமையை அதிகரிப்பது எது என்பதை அனுபவத்தில் பிரித்தறிவதே இங்கு முக்கியம்.':' The destination is mixed, so the same connection may provide help at one stage and add responsibility at another. The useful distinction is between the part that makes progress possible and the part that increases the load. Both belong in the interpretation of how this area develops.';
 return [first+reading];
}
function v255VargaReading(h,lang){
 const ta=lang==='ta',out=[];for(const v of arr(h.assessment?.varga).filter(v=>Number(v.n)>1)){
 const title=`D${v.n}`,ruler=v251Planet(h.lord,lang);
 const line=ta?`${h.house}-ஆம் பாவத்தின் அதிபதி ${ruler} மற்றும் சம்பந்தப்பட்ட காரகங்களை D${v.n} துணை ஜாதகத்தில் இணைத்துப் பார்த்த மதிப்பீடு ${v.state==='support'?'ஆதரவாக':v.state==='pressure'?'கவனம் தேவைப்படும் நிலையில்':'கலப்பு நிலையில்'} உள்ளது.`:`The combined assessment of ${ruler}, ruler of house ${h.house}, and the relevant significators in D${v.n} is ${v.state==='support'?'supportive':v.state==='pressure'?'demanding':'mixed'}.`;
 const meaning=ta?(v.state==='support'?(h.state==='pressure'?' முதன்மைப் பாவத்தில் சிரமம் இருப்பினும் இந்தத் துணை ஆதாரம் இருப்பதால் முழுமையாக எதிர்மறையாக வாசிக்க வேண்டியதில்லை. ஆரம்பத்தில் தேவைப்படும் முயற்சிக்குப் பிறகு நிலைப்படுத்திக்கொள்ளும் பக்கம் உள்ளதா என்பதை வாழ்க்கைச் சூழலுடன் பார்க்கலாம்.':' முதன்மை ஜாதகத்தில் கூறிய வாய்ப்பிற்கு மற்றொரு ஆதாரம் கிடைக்கிறது. ஒரு நல்ல நிகழ்வு மட்டும் அல்லாமல் அதன் பின்னர் ஏற்கும் பொறுப்பையும் நடத்திச் செல்லும் பக்கம் உள்ளதாகப் புரிந்துகொள்ளலாம்.'):v.state==='pressure'?' முதன்மை ஜாதகத்தில் வாய்ப்பு இருந்தாலும் அதை நீடிக்கச் செய்வதில் கூடுதல் கவனம் தேவைப்படலாம். தொடங்குவது, நிலைபெறுவது ஆகியவற்றை ஒரே முடிவாகச் சொல்லாமல் இரண்டு கட்டங்களாக வாசிப்பதற்கு இது ஒரு காரணம்.':' இந்தத் துணை ஜாதகம் மட்டும் தெளிவான சாதகமோ பாதகமோ கூறவில்லை. ஆகவே மேலே உள்ள பாவ அதிபதி, கிரகத் தொடர்பு மற்றும் காலப் பலனுடன் சேர்த்தே முடிவு தொடர்கிறது.'):(v.state==='support'?(h.state==='pressure'?' This provides a supporting counterweight to a demanding main-house reading. It leaves room to consider how stability might develop after the initial effort, rather than treating the entire area as negative.':' This adds another supporting layer to the main-chart opportunity, including the responsibilities that follow an initial opening.'):v.state==='pressure'?' Even where the main chart offers an opening, maintaining it can require more care. This is one reason to distinguish starting something from becoming settled in it.':' This division alone does not provide a clear positive or negative answer; it remains part of the combined assessment with the ruler, other influences and timing.');
 out.push({title:ta?`${title} துணை ஜாதகம் தரும் கூடுதல் விளக்கம்`:`What ${title} adds to the reading`,paragraphs:[line+meaning]});
 }return out;
}
function v253House(h,ctx,e,lang){
 const old=v252HouseChapter(h,ctx,e,lang),n=Number(h.house),b=V253_HOUSE[n],ta=lang==='ta';
 if(!b||ctx.age!=null&&ctx.age<=18)return old;
 const state=h.state,lead=state==='support'?b[ta?1:0]:state==='pressure'?b[ta?3:2]:b[ta?1:0]+' '+b[ta?3:2];
 const route=V253_ROUTE[Number(h.lordHouse)],planet=v251Planet(h.lord,lang);
 const link=route&&h.lord?(ta?`${n}-ஆம் பாவ அதிபதி ${planet}, ${h.lordHouse}-ஆம் பாவத்தில் இருப்பதால் இந்த அனுபவம் ${route[1]} வழியாக வெளிப்படலாம்.`:`The ruler of house ${n}, ${planet}, is in house ${h.lordHouse}. This connects the experience with ${route[0]}.`):'';
 const result=ta?(state==='support'?'மொத்த முடிவு: ஆதரவு மேலோங்குகிறது.':state==='pressure'?'மொத்த முடிவு: கவனமும் முயற்சியும் அதிகம் தேவைப்படும் நிலை.':'மொத்த முடிவு: ஆதரவும் சவாலும் இணைந்த கலப்பு நிலை.'):(state==='support'?'Overall result: support is stronger.':state==='pressure'?'Overall result: greater care and effort are needed.':'Overall result: a mixed pattern of support and pressure.');
 const sections=[{title:ta?'இந்தப் பாவத்தின் மொத்த முடிவு':'Overall reading of this house',paragraphs:[result+' '+lead]}];
 for(const row of V254_HOUSE_DEPTH[n]||[]){sections.push({title:row[ta?1:0],paragraphs:state==='support'?[row[ta?3:2]]:state==='pressure'?[row[ta?5:4]]:[row[ta?3:2],row[ta?5:4]]})}
 sections.push({title:ta?'பாவ அதிபதி காட்டும் வாழ்க்கைத் தொடர்பு':'The life connection shown by the house ruler',paragraphs:v255HouseConnections(h,e,lang).length?v255HouseConnections(h,e,lang):[link]},{title:ta?'அதிபதியின் பலத்தைச் சேர்த்துப் பார்க்கும்போது':'Reading the strength of the ruler',paragraphs:[v255RulerReading(h,lang)]});
 for(const pn of arr(h.occupants)){
 const meaning=h.planetReadings?.[pn]?.[lang];
 sections.push({title:ta?`${v251Planet(pn,lang)} இந்தப் பாவத்தில் இருப்பதன் பொருள்`:`What ${pn} in this house contributes`,paragraphs:[ta?`${n}-ஆம் பாவத்தில் ${v251Planet(pn,lang)} இருப்பது இந்த மதிப்பீட்டில் நேரடியாகச் சேர்க்கப்படுகிறது.${meaning?' '+meaning:''}`:`${pn} occupies house ${n} and contributes directly to this assessment.${meaning?' '+meaning:''}`]});
 }
 const sup=arr(h.supportAspects).map(p=>v251Planet(p,lang)),prs=arr(h.pressureAspects).map(p=>v251Planet(p,lang));
 sections.push({title:ta?'பார்வை பலமும் காரக ஆதரவும்':'Aspects and significator support',paragraphs:[sup.length?(ta?`${sup.join(', ')} பார்வை இங்கு ஆதரவாகக் கணக்கிடப்படுகிறது. பாவ அதிபதி காட்டும் முயற்சியை முன்னெடுத்துச் செல்ல இது ஒரு துணைக் காரணம்.`:`The aspect from ${sup.join(', ')} counts as support, adding a supporting influence alongside the house ruler.`):'',prs.length?(ta?`${prs.join(', ')} பார்வை கூடுதல் பொறுமையும் ஒழுங்கும் தேவைப்படும் பக்கத்தைக் காட்டுகிறது. ஆதரவு இருந்தாலும் இந்தச் சுமையைப் புறக்கணிக்க முடியாது; மேலே கூறிய மொத்த முடிவில் இரு தரப்பும் சேர்க்கப்பட்டுள்ளன.`:`The aspect from ${prs.join(', ')} adds pressure that calls for patience and organisation. Any supporting influences and this pressure are combined in the overall result above.`):'',pickLang(h.karaka,lang)]});
 sections.push(...v255VargaReading(h,lang));
 sections.push({title:ta?'உடல் பராமரிப்புடன் தொடர்புடைய பகுதி':'Connection with everyday physical care',paragraphs:[old.paragraphs[1]]},{title:ta?'வசதிகள், பொருட்கள் மற்றும் நடைமுறைத் தேவைகள்':'Resources and practical needs',paragraphs:[old.paragraphs[2]]});
 return {...old,...v254Sections(sections)};
}

const V253_EVENT_PROSE={"career_progress": ["You may be asked to handle work whose result is noticed more directly. This can build your standing when you have enough authority to match the responsibility; otherwise it may initially feel like a heavier workload.", "உங்கள் வேலையின் முடிவு நேரடியாகக் கவனிக்கப்படும் பொறுப்பு கிடைக்கலாம். அதற்கேற்ற முடிவெடுக்கும் அதிகாரமும் இருந்தால் தொழில் மதிப்பு வளரும்; அதிகாரமின்றி பொறுப்பு மட்டும் கூடினால் முதலில் பணிச்சுமையாக உணரப்படலாம்."], "first_job": ["A new work opening can help turn an existing skill into regular experience. If you are already established, read this as a new assignment or professional connection, rather than assuming you must begin your career again.", "புதிய வேலை வாய்ப்பு ஏற்கனவே உள்ள திறனைத் தொடர்ந்து பயன்படுத்தும் அனுபவமாக மாற்றலாம். நீங்கள் ஏற்கனவே தொழிலில் இருந்தால் இது புதிய பணி அல்லது தொழில் தொடர்பாக அமையலாம்; மீண்டும் ஆரம்ப நிலையிலிருந்து தொடங்க வேண்டும் என்ற பொருள் இல்லை."], "career_stability": ["Work becomes more settled when expectations, recurring responsibilities and the people relying on you become clearer. The useful change may be a dependable routine or returning work, even without a dramatic change in title.", "எதிர்பார்ப்பு, தொடர்ச்சியான பொறுப்பு, உங்களை நம்பி வேலை கொடுப்பவர் ஆகியவை தெளிவாகும்போது தொழில் நிலை பெறலாம். பெரிய பதவி மாற்றம் இல்லாமல்கூட ஒழுங்கான பணி அல்லது மீண்டும் வரும் வேலை வாய்ப்பு நிம்மதியைத் தரலாம்."], "promotion": ["An opening for greater responsibility can arise through the work you have already demonstrated. Before accepting, understand whether the change includes decision-making power, support and a clear way to assess your contribution.", "ஏற்கனவே செய்து காட்டிய வேலையின் அடிப்படையில் உயர்ந்த பொறுப்பு கிடைக்க வாய்ப்பு உள்ளது. அதை ஏற்கும்போது முடிவெடுக்கும் அதிகாரம், உதவி, உங்கள் பங்களிப்புக்கான மதிப்பீடு ஆகியவை எவ்வாறு இருக்கும் என்பதைத் தெளிவுபடுத்துங்கள்."], "job_change": ["A different work arrangement may become attractive because the present role no longer meets an important need. The change could involve location, schedule or method of work as well as an employer; compare the specific improvement before deciding.", "தற்போதைய வேலையில் முக்கியமான தேவை நிறைவேறாததால் வேறு பணி அமைப்பு கவரக்கூடும். இது நிறுவன மாற்றம் மட்டுமல்ல; இடம், நேரம் அல்லது வேலை முறை மாற்றமாகவும் இருக்கலாம். எந்தக் குறை தீரும் என்பதை ஒப்பிட்டுப் பார்த்து முடிவெடுங்கள்."], "role_change": ["The people you work with or the task you are responsible for may change. This can make an existing job feel new; a clear handover and agreement about who decides what will help the transition.", "உங்களுடன் பணிபுரியும் குழு அல்லது உங்களுடைய பொறுப்பு மாறலாம். அதனால் அதே வேலையே புதிய அனுபவமாகத் தோன்றலாம்; பணியை ஒப்படைக்கும் முறையும் முடிவெடுக்கும் எல்லையும் தெளிவாக இருந்தால் மாற்றம் சுலபமாகும்."], "skill_growth": ["A skill develops best when it is used on an actual task rather than studied without application. Completing one useful piece of work can reveal both your progress and the part that still needs practice.", "கற்ற திறனை உண்மையான வேலையில் பயன்படுத்தும்போது வளர்ச்சி தெளிவாகத் தெரியும். ஒரு பயனுள்ள வேலையை முடித்துப் பார்ப்பது எவ்வளவு முன்னேறியுள்ளீர்கள், எங்கு இன்னும் பயிற்சி தேவை என்பதை அறிய உதவும்."], "communication": ["Explaining an idea clearly may become as important as knowing the answer. Listening to the other person’s question, choosing simple words and following up can make your knowledge more useful to others.", "பதில் தெரிந்திருப்பதுடன் அதைத் தெளிவாக விளக்குவதும் முக்கியமாகலாம். மற்றவர் என்ன கேட்கிறார் என்பதைக் கேட்டுப் புரிந்து, எளிய சொற்களில் கூறி, பின்னர் சந்தேகம் தீர்ந்ததா எனக் கவனிப்பது உங்கள் அறிவைப் பயனுள்ளதாக மாற்றும்."], "recovery": ["A delayed matter may become easier to approach after you understand why the earlier attempt stalled. Recovery is more likely to come through a corrected method or a smaller workable commitment than by repeating the same approach more forcefully.", "முந்தைய முயற்சி ஏன் தடைப்பட்டது என்பதைப் புரிந்துகொண்ட பிறகு நிலுவையான விஷயத்தை மீண்டும் அணுகுவது சுலபமாகலாம். அதே முறையை மேலும் வேகமாகச் செய்வதை விட முறையைத் திருத்துவது அல்லது சிறிய அளவில் மீண்டும் தொடங்குவது உதவலாம்."], "restructure": ["You may need to rearrange an established pattern rather than abandon the whole direction. Decide which part still works, which part consumes effort without benefit and what can be changed without disturbing the useful foundation.", "முழுப் பாதையையும் விட்டுவிடாமல் பழகிய அமைப்பில் மாற்றம் செய்ய வேண்டியிருக்கலாம். எது இன்னும் பயன் தருகிறது, எது உழைப்பை மட்டும் வாங்குகிறது, அடித்தளத்தைப் பாதிக்காமல் எதை மாற்றலாம் என்று பிரித்துப் பாருங்கள்."], "business_start": ["An independent service or business idea may become practical when a specific group of people needs what you can provide. Begin by understanding that need and the work involved, so enthusiasm is supported by a repeatable service.", "நீங்கள் வழங்கக்கூடிய சேவைக்கு குறிப்பிட்ட சிலரிடம் தேவை இருந்தால் சுயதொழில் யோசனை நடைமுறைக்கு வரலாம். அந்தத் தேவையையும் அதை நிறைவேற்றும் உழைப்பையும் முதலில் அறிந்துகொள்வது தொடர்ந்து வழங்கக்கூடிய சேவையை உருவாக்க உதவும்."], "business_growth": ["Business progress can be visible through customers returning, clearer demand or more dependable delivery. A larger number of enquiries is useful only when you can serve them without weakening the quality that attracted them.", "பழைய வாடிக்கையாளர் மீண்டும் வருதல், தேவை தெளிவாகத் தெரிதல், சேவையைத் தவறாமல் வழங்குதல் ஆகியவற்றில் வியாபார வளர்ச்சி தெரியலாம். விசாரணைகள் அதிகரிப்பதுடன் சேவைத் தரத்தையும் காப்பாற்ற முடிகிறதா என்பதைப் பாருங்கள்."], "partnership": ["Working with another person may widen your reach or supply a skill you do not have. Discuss contribution, ownership of work and how disagreements will be handled before assuming that goodwill alone will keep the arrangement balanced.", "மற்றவருடன் இணைவதால் உங்கள் தொடர்பு விரிவடையலாம் அல்லது உங்களிடம் இல்லாத திறன் கிடைக்கலாம். யார் என்ன பங்களிப்பது, பணியின் உரிமை என்ன, கருத்து வேறுபாட்டை எப்படித் தீர்ப்பது என்பதை ஆரம்பத்திலேயே பேசுங்கள்."], "income": ["There may be more scope to earn through a skill or responsibility that is already becoming useful. Notice whether the additional income is dependable or tied to a temporary burst of work before treating it as a permanent change.", "ஏற்கனவே பயன்படத் தொடங்கிய திறன் அல்லது பொறுப்பின் மூலம் வருமான வாய்ப்பு விரிவடையலாம். கூடுதல் வரவு தொடர்ந்து வருமா அல்லது தற்காலிக வேலை அதிகரிப்பால் மட்டுமா என்பதை அறிந்த பிறகு அதற்கேற்ப திட்டமிடுங்கள்."], "savings": ["A steadier financial position depends on what remains after recurring commitments are met. Making those commitments visible can show why a higher income does not always produce the sense of security you expected.", "தொடர்ச்சியான கடமைகளை முடித்த பிறகு எவ்வளவு மீதமிருக்கிறது என்பதில்தான் நிதி நிலைத்தன்மை தெரியும். அந்தக் கடமைகளைத் தெளிவாகக் கணக்கிட்டால் வரவு உயர்ந்தும் எதிர்பார்த்த நிம்மதி ஏன் கிடைக்கவில்லை என்பது புரியலாம்."], "gain": ["A useful result may come through earlier effort, an established contact or a shared project. Look at the effort, time and continuing responsibility attached to the gain so that its practical value is clear.", "முன்னர் செய்த முயற்சி, பழைய தொடர்பு அல்லது கூட்டு பணியின் மூலம் பயன் கிடைக்கலாம். அதனுடன் இணையும் உழைப்பு, நேரம், தொடரும் பொறுப்பு ஆகியவற்றையும் பார்த்தால் அதன் உண்மையான மதிப்பு தெளிவாகும்."], "relationship": ["A relationship may become clearer when intentions are discussed openly. This can mean growing closer, understanding a difference or deciding what each person is genuinely ready to offer; it need not mean an immediate formal commitment.", "நோக்கங்களை வெளிப்படையாகப் பேசும்போது உறவு பற்றிய தெளிவு வரலாம். நெருக்கம் அதிகரித்தல், வேறுபாட்டைப் புரிதல், ஒவ்வொருவரும் எந்த அளவு பொறுப்பிற்கு தயாராக உள்ளனர் என்பதை அறிதல் என இது அமையலாம்."], "proposal": ["Family discussions can move beyond general interest toward practical questions about work, residence and responsibility. Progress is more meaningful when both individuals have space to express their own expectations alongside family preferences.", "திருமணப் பேச்சு பொதுவான ஆர்வத்திலிருந்து வேலை, வசிப்பிடம், பொறுப்பு போன்ற நடைமுறை விஷயங்களுக்கு நகரலாம். குடும்ப விருப்பத்துடன் இருவரின் தனிப்பட்ட எதிர்பார்ப்புகளையும் பேச இடம் இருக்கும்போது அந்த முன்னேற்றம் பொருள் பெறும்."], "marriage": ["Readiness for commitment becomes clearer through agreement about everyday life. Where a relationship already exists, the same emphasis can concern a shared decision or greater responsibility within that relationship rather than a new marriage.", "அன்றாட வாழ்க்கையை எப்படிப் பகிர்வது என்பதில் உடன்பாடு வரும்போது உறுதிப்பாட்டிற்கான தயார்நிலை தெளிவாகும். ஏற்கனவே திருமணமானவருக்கு இது புதிய திருமணத்தை அல்ல; தற்போதைய உறவில் கூட்டு முடிவு அல்லது பொறுப்பு உயர்வைக் குறிக்கலாம்."], "child_planning": ["Conversations about children may bring attention to care, time, support and shared expectations. Treat these as practical family decisions; the chart cannot establish fertility or promise the outcome of pregnancy.", "குழந்தை தொடர்பான பேச்சு பராமரிப்பு, நேரம், உதவி, இருவரின் எதிர்பார்ப்பு ஆகியவற்றை முன்னிலைப்படுத்தலாம். இவை குடும்பத் திட்டமிடலுக்கான விஷயங்கள்; ஜாதகத்தால் கருத்தரிக்கும் திறனையோ கர்ப்பத்தின் முடிவையோ உறுதி செய்ய முடியாது."], "family_expansion": ["A wider family role may become important, whether through caring for a child or taking responsibility for someone who depends on you. The useful question is how the household can share care without placing the entire load on one person.", "குழந்தைப் பராமரிப்பு அல்லது உங்களைச் சார்ந்திருப்பவருக்கான பொறுப்பு மூலம் குடும்பத்தில் உங்கள் பங்கு விரிவடையலாம். முழுச் சுமையும் ஒருவரிடம் சேராமல் வீட்டில் பராமரிப்பை எப்படிப் பகிரலாம் என்பதே முக்கியம்."], "higher_education": ["Further study may be useful when it deepens a subject you can apply or opens a clearly understood path. The attraction of a qualification should be weighed alongside the time and sustained interest needed to complete it.", "பயன்படுத்தக்கூடிய அறிவை ஆழப்படுத்தும்போது அல்லது தெளிவான பாதையைத் திறக்கும்போது மேல்படிப்பு பயனுள்ளதாக அமையலாம். தகுதி பெறும் விருப்பத்துடன் அதை முடிக்க வேண்டிய நேரமும் தொடர்ந்து படிக்கும் ஆர்வமும் உள்ளதா என்று பாருங்கள்."], "training": ["A focused course or practical training can address a specific gap in your work or studies. Choose the skill you want to use afterwards, then judge the training by how well it helps you perform that task.", "குறிப்பிட்ட பயிற்சி உங்கள் வேலை அல்லது படிப்பில் உள்ள ஒரு குறையை நிரப்பலாம். பிறகு எந்தத் திறனைப் பயன்படுத்த வேண்டும் என்பதைத் தீர்மானித்து, அதைச் செய்ய இந்தப் பயிற்சி எந்த அளவு உதவும் என்று பாருங்கள்."], "restart_study": ["An interrupted course or a postponed learning goal may become worth revisiting. Begin with the reason it stopped and arrange a more workable pace, rather than expecting motivation alone to remove the earlier difficulty.", "இடைநிறுத்திய படிப்பு அல்லது ஒத்திப்போட்ட கற்றல் இலக்கை மீண்டும் அணுகலாம். முன்பு ஏன் நின்றது என்பதை அறிந்து நடைமுறைக்கு ஏற்ற நேர ஒழுங்கை அமைப்பது, ஆர்வத்தை மட்டும் நம்புவதை விட உதவியாக இருக்கும்."], "home_change": ["A different residence may become relevant because of work, education or family convenience. Consider how the move changes the daily journey, privacy and available support, rather than judging the new place only by its appearance.", "வேலை, கல்வி அல்லது குடும்ப வசதிக்காக வேறு இடத்தில் வசிக்கும் எண்ணம் வரலாம். புதிய இடத்தின் தோற்றத்துடன் அன்றாடப் பயணம், தனியுரிமை, கிடைக்கும் உதவி ஆகியவை எப்படி மாறும் என்பதையும் பாருங்கள்."], "property_purchase": ["A home or property plan may become more concrete as needs become clearer. Keep the wish to settle separate from the actual responsibilities of ownership, and use verified practical information before making a commitment.", "தேவைகள் தெளிவாகும்போது வீடு அல்லது சொத்து பற்றிய திட்டம் உறுதியான வடிவம் பெறலாம். நிலையாக அமர வேண்டும் என்ற விருப்பத்துடன் உரிமையாளராக ஏற்கும் உண்மையான பொறுப்புகளையும் தனியாக மதிப்பிடுங்கள்."], "vehicle": ["Transport may become a practical decision because of changing travel needs. The useful choice is the one that fits regular use, upkeep and convenience, rather than simply marking an improvement in outward status.", "பயணத் தேவை மாறுவதால் வாகனம் பற்றிய முடிவு முக்கியமாகலாம். வெளிப்புற அந்தஸ்தை விட தொடர்ந்து பயன்படுத்துதல், பராமரிப்பு, வசதி ஆகியவற்றிற்கு ஏற்ற தேர்வே பயனுள்ளதாக இருக்கும்."], "repayment": ["Existing obligations may need a clearer order of attention. Bringing dates, amounts and responsibilities together can make a difficult commitment more understandable and reduce confusion about what can realistically be handled next.", "நிலுவைக் கடமைகளை எந்த வரிசையில் கவனிப்பது என்ற தெளிவு தேவைப்படலாம். தேதி, தொகை, பொறுப்பு ஆகியவற்றை ஒன்றாகப் பார்த்தால் அடுத்து நடைமுறையில் எதைச் செய்ய முடியும் என்பது புரியும்."], "competition": ["Progress may require demonstrating your ability under comparison or opposition. Preparation and a calm response to feedback are more useful than allowing the wish to defeat someone else to determine your direction.", "ஒப்பீடு அல்லது எதிர்ப்பு உள்ள சூழலில் திறனைச் செய்து காட்ட வேண்டியிருக்கலாம். மற்றவரை வெல்ல வேண்டும் என்ற எண்ணத்தை விட தயாரிப்பும் திருத்தங்களை அமைதியாக ஏற்றுச் செய்வதும் முன்னேற்றத்திற்கு உதவும்."], "litigation": ["An unresolved administrative or document-related matter may need organised attention. Keep records and distinguish what is confirmed from what has merely been said; a chart does not determine the outcome of a legal dispute.", "நிர்வாகம் அல்லது ஆவணம் தொடர்பான நிலுவை விஷயத்தை ஒழுங்காகக் கவனிக்க வேண்டியிருக்கலாம். பதிவுகளைப் பாதுகாத்து, உறுதியான தகவல் எது, வாய்வழியாகச் சொல்லப்பட்டது எது என்பதைப் பிரித்துப் பாருங்கள்; வழக்கின் முடிவை ஜாதகம் உறுதி செய்யாது."], "vitality": ["Your daily capacity is easier to understand when work, rest and routine are considered together. A demanding schedule can make ordinary tasks feel harder; actual symptoms and changes in health should be assessed on their own merits.", "வேலை, ஓய்வு, தினசரி ஒழுங்கு ஆகியவற்றை ஒன்றாகப் பார்க்கும்போது உங்கள் செயல்திறன் புரியும். அதிகச் சுமையால் சாதாரண வேலையும் கடினமாகத் தோன்றலாம்; உடல்நிலை மாற்றத்திற்கான காரணத்தை உண்மையான அறிகுறிகளின் அடிப்படையில் கவனிக்க வேண்டும்."], "recovery_routine": ["Rest and a manageable routine deserve attention when responsibilities are accumulating. This is a reflection on workload and care, not a prediction of a particular illness or accident.", "பொறுப்புகள் சேரும்போது போதிய ஓய்வும் சமாளிக்கக்கூடிய தினசரி ஒழுங்கும் முக்கியம். இது பணிச்சுமை மற்றும் பராமரிப்பு பற்றிய கவனம்; குறிப்பிட்ட நோய் அல்லது விபத்து வரும் என்ற கணிப்பு அல்ல."], "family_support": ["Help from family can become more useful when each person understands what is needed. A clear request may work better than expecting relatives to recognise an unspoken concern or to offer support in exactly your preferred way.", "என்ன உதவி தேவை என்பது புரிந்தால் குடும்ப ஆதரவு பயனுள்ளதாக அமையும். சொல்லாத கவலையை உறவினர் புரிந்துகொள்வார்கள் என்று எதிர்பார்ப்பதை விட தேவையைத் தெளிவாகக் கேட்பது உதவும்."], "family_duty": ["You may become the person others approach to organise a family matter. This can strengthen trust, but it helps to agree who will share the work so that being dependable does not mean becoming permanently responsible for everything.", "குடும்ப விஷயத்தை ஒழுங்குபடுத்த மற்றவர்கள் உங்களை அணுகலாம். அது நம்பிக்கையை வளர்க்கும்; அதே நேரத்தில் யார் எந்த வேலையைப் பகிர்வது என்று தீர்மானித்தால் எல்லாவற்றிற்கும் நீங்களே நிரந்தரப் பொறுப்பாளராக வேண்டியிருக்காது."], "parent_support": ["A parent or experienced elder may offer perspective that becomes useful in a difficult choice. The value may lie in practical help, an introduction or patient advice rather than agreement with every decision you make.", "கடினமான தேர்வில் பெற்றோர் அல்லது அனுபவமுள்ள பெரியவரின் பார்வை உதவலாம். உங்கள் எல்லா முடிவையும் ஏற்றுக்கொள்வதை விட நடைமுறை உதவி, தொடர்பு அல்லது பொறுமையான அறிவுரையாக அந்த ஆதரவு அமையலாம்."], "parent_duty": ["Home or parental responsibilities may require a more organised share of your time. Discuss needs early and separate what you can do personally from what can be shared with other family members.", "வீடு அல்லது பெற்றோர் தொடர்பான பொறுப்பிற்கு உங்கள் நேரத்தை ஒழுங்காகப் பகிர வேண்டியிருக்கலாம். தேவைகளை முன்பே பேசி, நீங்களே செய்ய வேண்டியது எது, மற்றவருடன் பகிரக்கூடியது எது என்பதைத் தீர்மானியுங்கள்."], "sibling_support": ["A sibling or familiar contact may help through information, cooperation or a practical introduction. Keeping expectations clear will protect the relationship if help is offered informally rather than through a defined arrangement.", "சகோதரர் அல்லது பழகிய தொடர்பின் மூலம் தகவல், ஒத்துழைப்பு, அறிமுகம் கிடைக்கலாம். முறையான ஏற்பாடு இல்லாமல் உதவி கிடைக்கும்போது எதிர்பார்ப்பைத் தெளிவாக வைத்திருப்பது உறவைப் பாதுகாக்கும்."], "initiative": ["A matter that has waited for someone else’s response may move when you make a clear first approach. Keep the request specific and follow through, so initiative becomes a completed step rather than another unfinished conversation.", "மற்றவரின் பதிலுக்காகக் காத்திருந்த விஷயத்தில் நீங்கள் தெளிவாக முதலில் அணுகினால் முன்னேற்றம் ஏற்படலாம். என்ன தேவை என்பதைச் சரியாகக் கூறி தொடர்ந்து கவனித்தால் முயற்சி முடிந்த செயலாக மாறும்."], "travel": ["A journey or distant contact may serve a useful purpose through learning, work or family needs. The meaning lies in what the connection makes possible, not necessarily in travelling a great distance.", "படிப்பு, வேலை அல்லது குடும்பத் தேவையின் வழியாக பயணம் அல்லது தொலைதூரத் தொடர்பு பயன் தரலாம். அதிக தூரம் செல்வதை விட அந்தத் தொடர்பால் என்ன பயன்பாடு கிடைக்கிறது என்பதே முக்கியம்."], "relocation": ["A move may be considered when a different place offers a clearer fit for work or family life. If you have already relocated, the question may concern settling in, maintaining distant ties or choosing the next arrangement.", "வேலை அல்லது குடும்ப வாழ்க்கைக்கு வேறு இடம் பொருத்தமாகத் தோன்றினால் இடமாற்றம் பற்றி யோசிக்கலாம். ஏற்கனவே இடம் மாறியிருந்தால் அங்கு நிலைபெறுதல், தொலைதூர உறவைப் பேணுதல் அல்லது அடுத்த ஏற்பாடு பற்றி இது அமையலாம்."], "recognition": ["Others may begin to notice the value of work that has been developing quietly. Recognition is most useful when it leads to trust and appropriate responsibility, rather than pressure to remain constantly visible.", "அமைதியாகச் செய்து வந்த வேலையின் மதிப்பை மற்றவர்கள் கவனிக்கத் தொடங்கலாம். எப்போதும் வெளிப்படையாகத் தெரிய வேண்டும் என்ற அழுத்தமாக இல்லாமல் நம்பிக்கையும் பொருத்தமான பொறுப்பும் கிடைக்கும்போது அங்கீகாரம் பயன் தரும்."], "leadership": ["You may have an opportunity to coordinate people or take responsibility for a shared result. Listening, setting a clear direction and deciding what can be delegated will matter more than making every decision yourself.", "மற்றவர்களை ஒருங்கிணைக்க அல்லது கூட்டு முடிவிற்குப் பொறுப்பேற்க வாய்ப்பு வரலாம். எல்லா முடிவையும் நீங்களே எடுப்பதை விட கருத்தைக் கேட்டு, திசையைத் தெளிவுபடுத்தி, பொறுப்பைப் பகிர்வது முக்கியமாகும்."], "opportunity": ["An opening becomes useful when it meets a skill or preparation you already have. Notice whether it solves an actual need in your life, so the excitement of something new does not obscure the work required to use it.", "ஏற்கனவே உள்ள திறன் அல்லது தயாரிப்புடன் பொருந்தும்போது வாய்ப்பு பயன்படும். புதியது என்ற ஆர்வத்துடன் அது உங்கள் உண்மையான தேவையைத் தீர்க்கிறதா, அதைப் பயன்படுத்த என்ன உழைப்பு தேவை என்பதையும் பாருங்கள்."], "guidance": ["A timely explanation or experienced person’s advice may help you recognise an option you had overlooked. Use it to sharpen your judgement, while keeping the final choice connected to your own circumstances.", "சரியான நேரத்தில் கிடைக்கும் விளக்கம் அல்லது அனுபவமுள்ளவரின் அறிவுரை கவனிக்காத வாய்ப்பைக் காட்டலாம். உங்கள் சூழலுடன் பொருத்திப் பார்த்து முடிவு செய்யும்போது அந்த வழிகாட்டல் பயன் தரும்."], "inner_growth": ["A quieter period of reflection may change how you understand an experience rather than changing the experience itself. Clarity can develop when you give space to grief, uncertainty or questions without demanding an immediate answer.", "அமைதியாகச் சிந்திக்கும் நேரம் நடந்த அனுபவத்தை மாற்றாவிட்டாலும் அதைப் புரிந்துகொள்ளும் முறையை மாற்றலாம். துயரம், குழப்பம் அல்லது கேள்விக்கு உடனே பதில் வேண்டும் என்று வற்புறுத்தாமல் இடம் கொடுக்கும்போது தெளிவு வரலாம்."], "practice": ["A simple, sustainable spiritual or reflective practice may become a source of steadiness. Its place in life is strongest when it supports kindness, attention and practical responsibility rather than replacing action that is needed.", "தொடர்ந்து செய்யக்கூடிய எளிய வழிபாடு அல்லது சிந்தனைப் பழக்கம் மனநிலைக்கு நிலைத்தன்மை தரலாம். செய்ய வேண்டிய செயலை மாற்றாமல் அன்பு, கவனம், நடைமுறைப் பொறுப்பு ஆகியவற்றிற்கு உதவும்போது அதன் பயன் பொருள் பெறும்."]};
function v253Domain(d,ctx,lang){
 const ta=lang==='ta',meta=H_DOMAINS[d.id]||{en:d.id,ta:d.id},events=v253Unique(arr(d.events?.[lang]).map(x=>cleanEvent(x,lang))),route=V253_ROUTE[Number(d.lordHouse)],lord=v251Planet(d.lord,lang),depth=arr(d.depth?.[lang]);
 if(!events.length)return null;
 const expressions=events.join(ta?'; ':'; '),title=meta[lang];
 const opening=ta?(d.state==='support'?`${title} தொடர்பாக ${expressions} ஆகியவற்றிற்கு ஜாதகத்தில் ஆதரவு உள்ளது. வாய்ப்பு கிடைத்ததும் எடுத்துக்கொள்ளும் பொறுப்பைத் தொடர்ந்து நிறைவேற்றுவதன் மூலம் இந்த ஆதரவு வெளிப்படலாம்.`:d.state==='pressure'?`${expressions} பற்றிய எதிர்பார்ப்பு இருந்தாலும் தற்போதைய தடையைச் சரிசெய்வதற்கு முக்கியத்துவம் கொடுக்க வேண்டிய அமைப்பு உள்ளது. விருப்பம் இல்லாததால் அல்ல; நேரம், சுமை, நடைமுறை வசதி ஆகியவை ஒத்துவர வேண்டும்.`:`${title} ஒரே நேரான பாதையில் செல்லாமல் சில வாய்ப்புகளும் சில மாற்றங்களும் கலந்து அமையலாம். ${expressions} ஆகியவற்றில் எது உங்கள் தற்போதைய வாழ்க்கைக்கு பொருந்துகிறது என்பதை வைத்து அடுத்த முடிவை எடுப்பது நல்லது.`):(d.state==='support'?`The chart gives usable support for ${expressions}. In ${title.toLowerCase()}, that support is most likely to become visible when an opening is followed by consistent delivery.`:d.state==='pressure'?`The wish for ${expressions} may be present, but the current obstacle deserves attention first. This is a question of readiness, workload and practical support rather than a reason to abandon the goal.`:`There is room for ${expressions}, alongside constraints that can alter the sequence. Start with the part that fits your present circumstances instead of expecting every possibility to develop together.`);
 const why=route?(ta?`${d.house}-ஆம் பாவ அதிபதி ${lord}, ${d.lordHouse}-ஆம் பாவத்தில் இருப்பது இந்த முடிவுக்கான ஒரு காரணம். அதனால் ${route[1]} இந்த வாழ்க்கைப் பகுதியின் முன்னேற்றத்துடன் இணைகிறது.`:`One reason for this reading is that ${lord}, ruler of house ${d.house}, occupies house ${d.lordHouse}. This connects progress here with ${route[0]}.`):'';
 const occ=arr(d.occupants).map(p=>v251Planet(p,lang)),occupancy=occ.length?(ta?`${occ.join(', ')} ${d.house}-ஆம் பாவத்தில் இருப்பதும் சேர்த்துக் கணிக்கப்படுகிறது. பாவ அதிபதி காட்டும் வழியுடன் இந்த நேரடித் தொடர்பையும் இணைத்தே முடிவு எடுத்துள்ளோம்.`:`${occ.join(', ')} occupying house ${d.house} is also part of the assessment, alongside the route indicated by its ruler.`):'';
 const div=d.vargaAvailable?(ta?`D${d.varga} துணை ஜாதகத்தில் இந்தப் பாவ அதிபதியின் நிலை ${d.vargaStrength>0?'ஆதரவாக உள்ளது. முதன்மை ஜாதகத்தில் தெரியும் வாய்ப்பை நிலைப்படுத்த இது துணை செய்யலாம்':d.vargaStrength<0?'சில சவால்களைக் காட்டுகிறது. ஆரம்ப வாய்ப்பு கிடைத்த பிறகும் அதைத் தக்கவைக்கும் முயற்சி தேவைப்படலாம்':'கலப்பு நிலையில் உள்ளது. முதன்மை ஜாதகத்தின் வாய்ப்புடன் நடைமுறைத் தயாரிப்பையும் சேர்த்துப் பார்க்க வேண்டும்'}.`:`In D${d.varga}, the relevant ruler ${d.vargaStrength>0?'has supporting strength, adding a reason that an initial opening can become more durable':d.vargaStrength<0?'is less well supported, so maintaining an opening can take more work than obtaining it':'gives a mixed indication, making preparation important alongside the main-chart promise'}.`):'';
 const fields=arr(d.fields?.[lang]),work=fields.length?(ta?`வேலைத் திசையைப் பொறுத்தவரை ${fields.join(', ')} ஆகியவற்றுடன் தொடர்புடைய திறன்கள் கவனிக்கத்தக்கவை. ஒரே குறிப்பிட்ட வேலைப்பெயராக இதைச் சுருக்க வேண்டாம்; அந்தப் பணியில் பயன்படுத்தப்படும் திறனே முக்கியம்.`:`Possible work directions include ${fields.join(', ')}. These describe skills and kinds of responsibility to explore, rather than one job title that the chart can guarantee.`):'';
 const detail=arr(d.eventIds).map(id=>V253_EVENT_PROSE[id]?.[ta?1:0]).filter(Boolean);
 const sections=[{title:ta?'இந்தத் துறையின் தெளிவான முடிவு':'The overall result in this area',paragraphs:[opening]},{title:ta?'இந்த முடிவுக்கான ஜாதக அடிப்படை':'Chart evidence behind this reading',paragraphs:[why,occupancy,div]},{title:ta?'உங்கள் வாழ்க்கையில் வெளிப்படும் விதம்':'How this can develop in everyday life',paragraphs:[work,pickLang(d.context,lang)]}];
 for(const row of V255_DOMAIN_DEPTH[d.id]||[])sections.push({title:row[ta?1:0],paragraphs:[row[ta?3:2]]});
 for(let i=0;i<arr(d.eventIds).length;i++){const id=d.eventIds[i],reading=V253_EVENT_PROSE[id]?.[ta?1:0];if(reading)sections.push({title:cleanEvent(arr(d.events?.[lang])[i]||id,lang),paragraphs:[reading]})}
 return {id:d.id,title,...v254Sections(sections)};
}
function v253Phase(z,e,lang){
 const ta=lang==='ta',p=arr(z.priorities),title=`${z.start} → ${z.end} · ${v251Planet(z.md,lang)}–${v251Planet(z.ad,lang)}`;
 const md=arr(e.houses).find(h=>arr(h.occupants).includes(z.md)),ad=arr(e.houses).find(h=>arr(h.occupants).includes(z.ad));
 const intro=md&&ad?(ta?`${v251Planet(z.md,lang)} தசை, ${v251Planet(z.ad,lang)} புக்தி நடைபெறும் இந்தக் கட்டத்தில் பிறப்பு ஜாதகத்தின் ${md.house} மற்றும் ${ad.house}-ஆம் பாவத் தொடர்புகள் காலப் பலனில் பங்கு பெறுகின்றன.`:`During this ${v251Planet(z.md,lang)}–${v251Planet(z.ad,lang)} period, the natal placements in houses ${md.house} and ${ad.house} contribute to the timing assessment.`):'';
 const sections=[{title:ta?'இந்தக் காலத்தின் ஜாதகப் பின்னணி':'Chart background for this period',paragraphs:[intro]}];
 for(const [planet,role]of [[z.md,ta?'தசாநாதன்':'Mahadasha lord'],[z.ad,ta?'புக்திநாதன்':'Bhukti lord']]){
 const house=arr(e.houses).find(h=>arr(h.occupants).includes(planet)),reading=house?.planetReadings?.[planet]?.[lang];
 if(reading&&(z.age==null||z.age>18))sections.push({title:`${role} ${v251Planet(planet,lang)}`,paragraphs:[ta?`${z.start} முதல் ${z.end} வரையிலான இந்தக் கட்டத்தில் ${role} ${v251Planet(planet,lang)} பிறப்பு ஜாதகத்தின் ${house.house}-ஆம் பாவத்தில் இருப்பதை இணைத்துப் பார்க்கிறோம். அங்கு இந்தக் கிரகம் குறிக்கும் இயல்பு: ${reading}. கீழே கூறப்படும் நிகழ்வு அல்லது பொறுப்பை அணுகும் விதத்தில் இந்தப் பின்னணி பங்கு பெறலாம்.`:`In the period from ${z.start} to ${z.end}, ${role} ${planet} occupies natal house ${house.house}. Its natal expression there is: ${reading}. This provides context for how the opportunities or responsibilities below may be approached.`]});
 }

 for(const q of p){const event=pickLang(q.event,lang);if(!event)continue;const prose=z.age!=null&&z.age<21?'':V253_EVENT_PROSE[q.eventId]?.[ta?1:0]||'';
 const state=ta?(q.state==='support'?'முன்னெடுக்க உதவும் காலச் சுட்டி உள்ளது':q.state==='pressure'?'முதலில் உள்ள சிரமத்தைச் சரிசெய்ய வேண்டிய காலம்':'வாய்ப்புடன் சில நடைமுறைச் சிக்கல்களும் கலந்து வரலாம்'):(q.state==='support'?'the period offers supporting indications':q.state==='pressure'?'the immediate emphasis is on resolving the difficulty':'opportunity and practical constraints may arrive together');
 sections.push({title:pickLang(q.title,lang),paragraphs:[`${event}: ${state}.`,prose]})}
 const wins=arr(e.timeline).filter(w=>w.start<=z.end&&w.end>=z.start);
 for(const w of wins){const start=w.start<z.start?z.start:w.start,end=w.end>z.end?z.end:w.end;sections.push({title:`${start} → ${end}`,paragraphs:[pickLang(w.primary,lang),pickLang(w.secondary,lang),pickLang(w.action,lang)]})}
 if(z.age!=null&&z.age<=18)sections.unshift({title:ta?'வயதிற்கேற்ற வாசிப்பு':'Age-appropriate context',paragraphs:[v252StageLabel(z.age,lang)]});
 return {title,...v254Sections(sections)};
}
